programs.sol:
"""Short vowel/consonant continuations after h-containing spelling fragments.

The largest positive rules are for short u/o spellings with labial endings,
especially after a short 'th' fragment. Some front-i continuations are negative.
Accented vowels are read by their base letter. A few analogous Greek/Thai
spellings and document-initial comment/control markers are handled separately.
This is a sparse approximation, not a general word or pronunciation model.
"""
import re
import unicodedata

READS: tuple[str, ...] = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].lower()
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    initial_cr = raw == '\r' and (first or carry[1])
    carry = (doc, initial_cr)
    if raw == '\r' and initial_cr:
        return carry, -3.14
    if first:
        return carry, -4.21 if raw == '//\n' else 0.0
    p = prefix.token_strings[-2].lower()
    if not raw or raw[0].isspace():
        return carry, 0.0

    # Greek theta/front vowels; Thai h/th followed by long-u.
    if p.endswith('θ') and raw[0] in 'ηι':
        return carry, -2.5
    if raw.startswith('ู') and p.endswith(('ถ', 'หน')):
        return carry, 6.5 if p.endswith('ถ') else 3.3

    if p.endswith('gh') or not (p.endswith('h') or
            any(d in p[-5:] for d in ('th', 'wh'))):
        return carry, 0.0
    th = p.endswith('th')
    short_th = th and len(p.strip()) <= 2
    decomposed = unicodedata.normalize('NFD', raw)
    s = ''.join(c for c in decomposed if unicodedata.category(c) != 'Mn')
    vowel_pair = re.fullmatch(r'u[aeiou]|iu', s)
    closed_u = (s.startswith('u') and len(s) <= 3
                and s.isascii() and s.isalpha()
                and not any(c in 'aeiou' for c in s[1:]))

    if re.fullmatch(r'[ou]mp(s|ing)?', s):
        value = 5.6 if th else 4.0
    elif re.fullmatch(r'op(s)?', s):
        value = 4.2 if th else 2.5 if 'th' in p or 'wh' in p else 1.3
    elif re.fullmatch(r'uff(ed)?', s):
        value = 2.5
    elif closed_u or vowel_pair:
        if short_th:
            if vowel_pair:
                value = 4.5
            else:
                value = 3.8 if len(s) == 1 else 1.6
        elif th:
            value = 0.7
        else:
            value = 1.3 if s.endswith('dd') else 0.3
        # Vietnamese horned-u as a single vowel, not every accented u.
        if (s == 'u' and '\N{COMBINING HORN}' in decomposed
                and len(decomposed) > 2):
            value = 3.5 if th else 3.0 if p.strip() == 'h' else 0.5
    elif s == 'ieu' and th:
        value = 1.7
    elif re.fullmatch(r'io[cst]?', s):
        value = 2.5 if th else 0.4
    elif re.fullmatch(r'om(a|as|s|pson)?', s):
        value = 1.2 if th else 0.3
    elif p.endswith('u') and re.fullmatch(r'o[td]', s):
        value = 4.0
    elif re.fullmatch(r'ou([dt]|nd(s|ing|ed)?|den|st)?', s):
        value = 1.3 if p.endswith('h') else 0.0
    elif s == 'i' and short_th:
        value = -2.0
    elif s.startswith('ith') and p.endswith('h'):
        value = -3.3 if th else -1.0
    elif s.startswith(('ist', 'ise', 'iz')) and p.endswith('h'):
        value = -0.9 if p.endswith(('th', 'sh', 'rh')) else -0.2
    elif s == 'ep' and th:
        value = -1.8
    else:
        value = 0.0
    return carry, value

"""A small orthographic approximation: isolated accented vowels are positive.

Weights distinguish the base vowel and its accent. Larger word pieces,
capitals, and common standalone accented function words are weaker. Acute
accents and umlauts are also weaker after complex Latin diacritics (carons,
double acutes, etc.), a rough cue to a different orthographic context.
A few typographic marks have signed responses. At document starts,
opening brackets and whitespace are positive; ordinary words have a small
negative baseline.
Most contextual variation in the real component is not captured here.
"""
import unicodedata as ud

READS = ()


def vowel_signal(ch):
    """Latin-1 accents and a few related, separately tokenized vowel letters."""
    ch = ch.lower()
    if ch in 'øœɛёїæ':
        return {'ø': 1.5, 'œ': 1.3, 'ɛ': 1.5,
                'ё': 2.0, 'ї': 0.45, 'æ': 0.55}[ch]
    if not ('\u00c0' <= ch <= '\u00ff'):
        return 0.0
    parts = ud.normalize('NFD', ch)
    if len(parts) != 2 or parts[0] not in 'aeiou':
        return 0.0
    base, mark = parts
    if mark == '\N{COMBINING ACUTE ACCENT}':
        return 0.6 if base == 'a' else 0.2
    if mark == '\N{COMBINING GRAVE ACCENT}':
        return 1.1 if base == 'e' else 0.5
    if mark == '\N{COMBINING CIRCUMFLEX ACCENT}':
        return 1.1 if base in 'aeo' else 0.4
    if mark == '\N{COMBINING DIAERESIS}':
        return {'a': 1.0, 'e': 1.1, 'i': 3.2,
                'o': 1.15, 'u': 0.24}[base]
    if mark == '\N{COMBINING TILDE}':
        return 1.4 if base == 'a' else 0.2
    if mark == '\N{COMBINING RING ABOVE}':
        return 0.6
    return 0.0


def orthographic_signal(raw):
    text = raw.strip()
    if 0 < len(text) <= 3 and text.isalpha():
        signal = sum(vowel_signal(c) for c in text)
        if signal:
            if len(text) > 1:
                # An accented vowel embedded in a larger word piece is weaker.
                if any(c in 'ãõёї' for c in text):
                    return 0.0
                factor = 0.45 if vowel_signal(text[-1]) else 0.15
                signal *= factor ** (len(text) - 1)
            elif raw[:1].isspace() and text.lower() in 'àèéó':
                # These are also common standalone grammatical words.
                signal *= 0.1
            if text.isupper():
                signal *= 0.45
            return signal
    if text == '··':
        return 0.64
    if len(text) == 1:
        if text == '¹':
            return -0.9
        if text in '£¢÷¶':
            return -0.65 if not raw[:1].isspace() else -0.15
        if text == '«':
            return 0.5
        if text in '·µ':
            return -0.25
        if text == '°':
            return 0.22
        if text == '\N{ARABIC SHADDA}':
            return 0.85
    return 0.0


# Diacritics characteristic of extended Latin orthographies.
COMPLEX_MARKS = {
    '\N{COMBINING CARON}',
    '\N{COMBINING DOUBLE ACUTE ACCENT}',
    '\N{COMBINING OGONEK}',
    '\N{COMBINING HOOK ABOVE}',
    '\N{COMBINING HORN}',
    '\N{COMBINING DOT BELOW}',
    '\N{COMBINING BREVE}',
}


def step(carry, prefix, upstream):
    doc, pos = prefix.document_ids[-1], prefix.position
    first = carry is None or carry[0] != doc
    last_complex = -1000 if first else carry[1]
    raw = prefix.token_strings[-1]
    for ch in raw:
        if 'LATIN' in ud.name(ch, ''):
            if (COMPLEX_MARKS.intersection(ud.normalize('NFD', ch))
                    or ch.lower() in 'đł'):
                last_complex = pos
    value = orthographic_signal(raw)
    if raw.strip().lower() in 'áéíóúäëïöü' and len(raw.strip()) == 1:
        if pos - last_complex <= 128:
            value *= 0.35
    if first and value == 0.0:
        text = raw.strip()
        if not text:
            value = 0.3
        elif text.isalpha():
            value = -0.15
        elif len(text) == 1 and ud.category(text) == 'Ps':
            value = 1.1 if raw[:1].isspace() else 0.6
    return (doc, last_complex), value

programs.haiku:
"""Layer 1, MLP down-projection, component 5889: an accented-letter detector.

What it does: the component fires (positive) on a token that is a single accented Latin
letter, such as ï, Ø, ё, â, ã, ê, ø, ö, ä, á, and is near zero on most other text.
How strongly it fires depends on the letter: ï, Ø, ё, â, ɛ, ã, ê, ø give large values,
and ó, à give small ones. The same letter after a space (" ä") gives half the value.
An opening French guillemet « also gives a moderate value.

Other tokens get 0, with two special cases:
  * the first token of a document has a small value that depends on its kind
    (digits and spaces slightly positive, letters slightly negative);
  * a "Title" followed by ":" at the start of a document gives the component's rare,
    very large activation (5.0).

The letter table holds typical activations for each letter, measured on training text.
Most of the component's variance is small, idiosyncratic per-token noise that no simple
rule captures, so the program explains only part of it.
"""

READS = ()

# Typical activation on each accented letter (the token is that letter).
ACCENT_ACTIVATION = {
    "ï": 3.0, "Ø": 2.0, "ё": 2.0, "â": 1.7, "ɛ": 1.6, "ã": 1.6, "ê": 1.4, "ø": 1.3,
    "ö": 1.0, "ë": 1.0, "è": 1.0, "ä": 0.9, "ô": 0.8, "á": 0.7, "æ": 0.7, "Ö": 0.7,
    "ò": 0.6, "å": 0.5, "Ä": 0.5, "ó": 0.4, "à": 0.4,
}

GUILLEMETS = {" «": 0.5, "«": 0.4}

# Mean activation of the first token of a document, by kind of token.
FIRST_TOKEN_ACTIVATION = {"digit": 0.26, "space": 0.30, "letter": -0.13, "other": -0.07}

TITLE_COLON_ACTIVATION = 5.0


def kind_of(token):
    if token.strip() == "":
        return "space"
    if token.isdigit():
        return "digit"
    if token.isascii() and token.isalpha():
        return "letter"
    return "other"


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    token = strings[-1]
    starts_doc = len(strings) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if starts_doc:
        return carry, FIRST_TOKEN_ACTIVATION.get(kind_of(token), 0.0)
    if token == ":" and len(strings) >= 3 and strings[-2] == "Title" and strings[-3] == "<|endoftext|>":
        return carry, TITLE_COLON_ACTIVATION
    if token in GUILLEMETS:
        return carry, GUILLEMETS[token]
    if token in ACCENT_ACTIVATION:
        return carry, ACCENT_ACTIVATION[token]
    if token[:1] == " " and token[1:] in ACCENT_ACTIVATION:
        return carry, 0.5 * ACCENT_ACTIVATION[token[1:]]
    return carry, 0.0

programs.sol:
"""Detect the beginnings of quoted payloads and enumerated items.

The strongest regular cases are a quote after a quoted dictionary key, a
here-document's opening EOF, and list-label parentheses. Smaller rules handle
literal separators and document-initial text. The unusually large response
to the second digit of an initial '12' is kept as an explicit exception.
Most word-identity variation is deliberately left unexplained.
"""
import re
import unicodedata

READS = ()
TEXT_LABELS = {'name', 'title', 'description', 'label', 'caption', 'text',
               'content', 'message', 'question', 'comment', 'summary'}
CODE_TYPES = {'int', 'string', 'float', 'double', 'bool', 'boolean', 'void'}


def predict(token, previous, tail, age):
    s = token.strip()
    if (len(s) >= 2 and set(s) == {'·'}
            and (age == 0 or previous.strip().endswith('·'))):
        return 5.15
    if age == 1 and previous == '1' and token == '2':
        return 7.16
    if token == '\n' and re.search(r'<<\s*EOF$', tail):
        return 2.2
    if s == 'EOF':
        return 2.85 if re.search(r'<<\s*[\'"]?$', tail) else 0.23
    if age == 0:
        if s.startswith('<|'):
            return -0.29
        if s in CODE_TYPES:
            return -1.2
        if s in {'import', 'from'}:
            return 1.9 if token == s else 0.5
        if s in {'a', 'an', 'the', 'A', 'An', 'The', 'I'}:
            return 0.43
        if s in {'\\n', '\\t'}:
            return 2.75
        if s.startswith(('\\\"', '`\\')):
            return 1.95
        if s and s[0] in '"“„' and (len(s) == 1 or s[1].isalpha()):
            return 0.9
        script = unicodedata.name(s[0], '') if s else ''
        if 'CYRILLIC' in script or 'GREEK' in script:
            return 1.45
        return 0.0

    # Quotes whose token contains only punctuation, not part of a word.
    q = s.replace('\\', '')
    if q in {'"', "'", '`', '("', "('", '="', "='", ':"'}:
        before = tail.rstrip()
        quote = q[-1]
        if q.startswith('='):
            field = re.search(r'([A-Za-z]+)$', before)
            name = field.group(1).lower() if field else ''
            if name.startswith('on'):
                return 1.65
            return 0.65 if name in TEXT_LABELS else 0.23
        if q == ':"':
            return 0.4
        if before.endswith(('":', "':")):
            field = re.search(r'''['"]([^'"\n]+)['"]:\s*$''', before)
            name = field.group(1).lower() if field else ''
            if name in TEXT_LABELS:
                return 1.33 if quote == '"' else 1.0
            return 1.14 if name == 'command' else 0.6
        if before.endswith(':'):
            return 0.18 if quote == '"' else 0.38
        if re.search(r'\bsed[^\n]*\s-[ni]$', before):
            return 1.65
        if before.endswith('=>'):
            return 0.8 if quote == '"' else 0.56
        if before.endswith('='):
            return 0.30
        if re.search(r'<<\s*$', before):
            return 0.95
        if q.startswith('('):
            return 0.10
        if re.search(r'\becho$', before):
            return 0.38
        return 0.0

    if s.startswith((')', '）', '].', ']).', '.)')):
        # A label with no unmatched opening parenthesis on the recent line.
        line = tail.rsplit('\n', 1)[-1]
        if (line.count('(') <= line.count(')')
                and re.search(r'(?:^|[\s{])(?:[0-9]{1,2}|[A-Za-z]|[ivx]{1,4})$', tail)):
            return 0.5 if s == ')' else 0.25
        return -0.025
    if s.endswith('\\') and s[0:1] in {')', ';', '*'}:
        return 0.30
    if s == ':':
        word = previous.strip().lower()
        if word in TEXT_LABELS:
            return 0.25
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, '', '', 0)
    _, previous, tail, age = carry
    token = prefix.token_strings[-1]
    value = predict(token, previous, tail, age)
    if token == '<|endoftext|>':
        return (document, '', '', 0), value
    return (document, token, (tail + token)[-100:], age + 1), value

programs.haiku:
"""Component layers.1.mlp.down_proj:5891 (a rank-one piece of the layer-1 MLP down projection).

What it does, in plain terms: it fires on the OPENING QUOTE of a string value written
right after a key, the way JSON, Python dicts and tool-call specs write them:

    {"name": "bash", "description": "Run a command", "command": "ls"}
            ^ fires here, on the quote that opens each value

It fires most for the keys "description" and "name" (as in tool and function-schema JSON), a
bit less for "command" and "message", less again for "type" and other keys. It also fires on:
  * the word that opens a shell here-document, as in  cat << 'EOF'  (the EOF tag);
  * the first token of a document when that token is Cyrillic or Greek text, or a code opener
    such as "import", "from", "package", "#!/", "/*", "###".
Everything else is predicted as 0. The values are rough averages measured on training text.
"""

import unicodedata

READS = ()

KEY_WEIGHTS = {"description": 1.5, "name": 1.3, "command": 1.1, "message": 0.9, "type": 0.7}
DEFAULT_KEY_WEIGHT = 0.5
QUOTE_TOKENS = (' "', '"', " '", "'", ' \\"', '\\"')
CODE_OPENERS = {"import", "from", "package", "#!/", "/*", "###"}
SCRIPT_START = ("CYRILLIC", "GREEK")


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    cur = tokens[-1]
    prev = tokens[-2] if len(tokens) > 1 else None

    # First token of a document (start of row, or right after <|endoftext|>).
    if prev is None or prev == "<|endoftext|>":
        word = cur.lstrip(" ")
        if word and unicodedata_script(word[0]) in SCRIPT_START:
            return carry, 1.5
        if word in CODE_OPENERS:
            return carry, 1.5

    # Opening quote of a string value.
    if cur in QUOTE_TOKENS and prev is not None:
        if prev == ":":
            return carry, 0.25  # colon with no key token before it (weak)
        if prev.endswith(":"):
            key = tokens[-3].strip(" \"'\\") if len(tokens) > 2 else ""
            return carry, KEY_WEIGHTS.get(key, DEFAULT_KEY_WEIGHT)
        if prev in (" =", "="):
            return carry, 0.3

    # Heredoc tag: an upper-case word right after "<<" (optionally with a quote between).
    if cur.isupper() and cur.isalpha() and any("<<" in s for s in tokens[-3:-1]):
        return carry, 2.8

    return carry, 0.0


def unicodedata_script(ch):
    """The first word of a character's Unicode name, e.g. 'CYRILLIC', 'GREEK', 'LATIN'."""
    return unicodedata.name(ch, "").split(" ")[0]

programs.sol:
"""A small approximation to several strong subword responses.

Give positive pulses to short word-initial Cyrillic/Arabic continuations,
Slavic pri-/przy- and split Persian mi-, Arabic vowel marks, and katakana
small tsu. Also distinguish undecodable token fragments and East Asian
character completions after a space-prefixed piece from ordinary text.
Split prefix completions get stronger pulses than longer stem pieces.
This captures recurring local spelling patterns, not all lexical variation.
"""
import regex

READS = ()
RUSSIAN_VOWELS = frozenset('аеёиоуыэюя')
ARABIC_SHORT_VOWELS = frozenset('َُِ')


def has_script(text, script):
    return bool(regex.search(r'\p{Script=' + script + '}', text))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = old
    for ch in token.lower():
        word = word + ch if ch.isalpha() else ''
    value = -0.002
    previous = ''
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == doc:
        previous = prefix.token_strings[-2]
    piece = token.strip()
    before = previous.strip()
    if '�' in token:
        value = -0.05 if token.startswith(' ') else 0.10
    elif not token.startswith(' ') and previous.startswith(' '):
        if len(before) == 1 and has_script(before, 'Cyrillic'):
            if piece.isalpha() and 1 <= len(piece) <= 2:
                value = 0.24 if piece[0].lower() in RUSSIAN_VOWELS else 0.11
        elif has_script(before, 'Arabic') and len(before) <= 3:
            if piece.isalpha():
                value = 0.26 if len(piece) == 1 else 0.07
    if token in ARABIC_SHORT_VOWELS:
        value = 0.32
    if token == 'ッ':
        value = 0.43
    # Completion of a word-initial multibyte character split by the tokenizer.
    raw = prefix.token_bytes[-1]
    if raw and 0x80 <= raw[0] < 0xC0 and previous.startswith(' '):
        joined_text = (prefix.token_bytes[-2] + raw).decode('utf-8', 'replace')
        if has_script(joined_text, 'Han'):
            value = 0.24
        elif any(has_script(joined_text, s) for s in
                 ('Hiragana', 'Katakana', 'Hangul')):
            value = 0.40
    if token.startswith('ー') and '�' in token:
        value = 0.39
    # The Persian imperfective prefix mi-, when split between tokens.
    if token in ('ی', 'ى') and old == 'م':
        value = 0.93

    for stem in ('при', 'pri', 'pří', 'prí', 'przy'):
        extra = len(word) - len(stem)
        if word.startswith(stem) and 0 <= extra <= 2:
            # Only count the token which first reaches this prefix.
            joined = bool(old) and not any(not c.isalpha() for c in token)
            if not joined or len(old) < len(stem):
                if stem == 'pri':
                    if joined:
                        value = 0.45 * 0.7 ** extra
                    else:
                        value = 0.30 if extra == 0 else 0.0
                elif joined:
                    value = 0.98 / (1.0 + 0.35 * extra)
                else:
                    value = (0.68, 0.34, 0.06)[extra]
            break
    return (doc, word[-20:]), value

"""A table/tab spelling and text-layout detector.

Recognize table words, the syllable 'tab' split across tokens (also in
Cyrillic/Arabic), table-reference spaces/numbers, and line-initial bars.
Capitalized references and some table types are stronger than SQL uses.
There are also responses to a document's 'Title:' header, escaped tabs,
and repeated middle-dot separators. Unrecognized text stays near zero.
"""
import re
from functools import lru_cache
import regex
from anyascii import anyascii

READS = ()
TABLE_WORDS = {'table', 'tables', 'tab', 'tabs', 'tabla', 'tablas',
               'tableau', 'tableaux'}
SQL_WORDS = {'create', 'alter', 'drop', 'from', 'join', 'into', 'update'}
TABLE_INTRODUCERS = {'following', 'multiplication', 'conversion',
                     'transition', 'text'}


@lru_cache(maxsize=8192)
def spelling(token):
    # Do not interpret Chinese/Japanese/Korean readings as Latin word pieces.
    if regex.search(r'[\p{Han}\p{Hiragana}\p{Katakana}\p{Hangul}]', token):
        return ''
    # Keep the written Arabic alif, which the transliterator normally drops.
    return anyascii(token.replace('ا', 'a')).lower()


def step(carry, prefix, upstream):
    token, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', '', '', False, 0)
    _, position, word, previous, older, line_start, pipes = carry
    s = spelling(token)
    bare = s.strip(' \t\r\n_./<>-()[]{}"\'`,:;')
    table = bare in TABLE_WORDS
    value = -0.23 if position == 0 else 0.0

    if table:
        value += 1.05 + 0.16 * token.startswith(' ')
        value += 0.78 * (bare == 'table' and 'Table' in token)
        value -= 0.95 * (previous.strip().lower() in SQL_WORDS)
        value += 2.77 * (previous.strip().lower() in TABLE_INTRODUCERS)
        if token in {'tab', 'Tab'} and word:
            value += 3.24
    if s.endswith('tab') and not table:
        value += 0.72
    if ((word.endswith('t') and s.startswith('ab')) or
            (word.endswith('ta') and s.startswith('b'))):
        value += 0.74
        if s in {'ab', 'abl'}:
            value += 4.67
            if regex.search(r'\p{Arabic}', token):
                value -= 2.66
    if word.endswith('tab') and re.match('[a-z]', s):
        value += 0.45 + 2.41 * s.startswith(('l', 'ul'))
    if word.endswith('table') and s in {'au', 'aux'}:
        value += 2.61
    if word.endswith('t') and token.startswith('BL'):
        value += 4.0  # TBL: the abbreviation for table.

    prev_table = previous.lower().strip() in TABLE_WORDS
    if prev_table:
        value += 1.86 * (token == ' ')
        value += 2.98 * (token.strip().lower() in {'above', 'below'})
    if token.strip().isdigit() and (prev_table or
            (previous == ' ' and older.lower().strip() in TABLE_WORDS)):
        value += 1.35
    if token in {'表', '表格'}:
        value += 0.84
    if previous.rstrip().endswith('<') and s == 'th':
        value += 2.94  # HTML table header cell.
    if token.lower().startswith('<table'):
        value += 2.06

    if line_start and token in {'|', '||', ' |'}:
        value += 2.20
        value += 4.77 * (pipes == 0 and token == '|')
        value -= 1.45 * token.startswith(' ')
    if token == '\\t':
        value -= 0.44
    if token.count('·') >= 2 and not token.strip('·'):
        value -= 2.01
    if previous == 'Title' and token == ':' and position == 1:
        value = 12.5
    else:
        value *= 1.1

    tail = re.search('[a-z]+$', s)
    if not tail:
        word = ''
