def predict(s, prev, before, raw, tail):
    word, prev, before = s.strip().lower(), prev.lower(), before.lower()

    # Han straight/direct, including a character split across UTF-8 tokens.
    if '直' not in s and '直'.encode() in tail + raw:
        return -12.3
    if word == '直':
        return -7.5
    if word in {'一直', '我一直', '直到', '一直到', '直至'}:
        return -5.7
    if word == '一直在':
        return -2.4
    if '直' in word:
        if len(word) > 3:
            return -0.6
        if word in {'直营', '直属'}:
            return -5.3
        return -1.7
    # The planting/breeding characters contain the same 直 shape.
    if word == '植' or (word == '殖' and prev.endswith('移')):
        return -3.4
    if word == '殖':
        return -0.8
    if '植' in word or '殖' in word:
        return -0.5
    if word == '직':
        return -5.0 if s.startswith(' ') else -3.0
    if word == 'trực':
        return -6.5
    if word.startswith('ực') and prev.endswith('tr'):
        return -12.5

    # Front/rounded vowels following consonant+r clusters in European words.
    if word.startswith('í') and (prev.endswith('př') or
                                 (prev == 'ř' and before.endswith('p'))):
        return -8.0 if word == 'í' else -4.7
    if word.startswith('í') and prev.endswith(('pr', 'ř')):
        return -3.5
    if word.startswith(('á', 'ø', 'ü')) and prev.endswith(('pr', 'př')):
        return -2.2
    if word == 'mo' and prev == 'í' and before.endswith('př'):
        return -3.1
    if word.startswith('ů') and prev.endswith('pr'):
        return -6.0

    # Cyrillic direct/direction/tension and simple roots, including splits.
    if 'пря' in word:
        return -4.6
    if word.startswith(('ям', 'я')) and prev.endswith('пр'):
        return -8.0
    if word.startswith('ря') and prev.endswith('п'):
        return -6.5
    if ((word == 'м' and prev.endswith('ря') and before.endswith('п')) or
            (word == 'мо' and prev == 'я' and before.endswith('пр'))):
        return -7.0
    if ((word.startswith('ост') and prev.endswith('пр')) or
            (word.startswith('рост') and prev.endswith('п'))):
        return -3.0
    if word == 'о' and prev.endswith('ост') and before.endswith('пр'):
        return -2.7
    if word == 'просто':
        return -0.65

    if word.startswith(('ο', 'ό')) and (prev.endswith('πρ') or
                                      (prev == 'ρ' and before.endswith('π'))):
        return -2.5
    if word == 'ิ' and prev.endswith('บร'):
        return -2.8
    if word.startswith('prism') or (word.startswith('ism') and prev.endswith('pr')):
        return -2.3
    if word.startswith(('ight', 'ait')) and prev.endswith(('stra', 'str')):
        return -4.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s, raw = prefix.token_strings[-1], prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        prev, before, tail = '', '', b''
    else:
        _, prev, before, tail = carry
    value = predict(s, prev, before, raw, tail)
    return (doc, s, prev, (tail + raw)[-2:]), value

