    extra_rate = doubles / (spaces + 3)
    number_rate = numbers / (spaces + 3)
    value = 0.0
    if s == ' ':
        if not prev:
            value = 0.42
        elif (prev2 + prev).endswith('\\n'):
            value = -2.1
        elif prev and set(prev) == {' '}:
            if len(prev) == 1:
                value = 1.1 if not line.strip() else 0.3
            elif position == 1:
                value = 3.6
            elif len(line) <= 8:
                value = 2.25 if number_rate < 0.28 else 1.72
            else:
                value = 1.4
        elif prev.endswith(('\n', '\r')):
            value = -2.0 if position == 1 else -0.85
        elif prev.isspace() and '\t' in prev:
            value = 1.25
        elif OPENING_QUOTE.search(line):
            value = -1.7
        else:
            value = -0.65 if extra_rate > 0.35 else (
                -0.3 if extra_rate > 0.14 else 0.0)
    elif s == '\t':
        if prev and set(prev) == {'\t'}:
            value = 0.46 if len(prev) == 1 else 0.94
        elif prev.strip().isdigit():
            value = -0.10

