"""layers.1.mlp.down_proj:5901, a "padding space" detector.

The component fires on a lone space token (also a lone tab or no-break space) and
is near zero on almost everything else. Qwen's tokenizer gives a space that comes
right before a number its own token, so the bare space is what pads a column before
a number: the line-number gutter of a numbered listing, or column-aligned output.
Its sign and size depend on what came just before the space. The program only reads
the tokens up to this one (the model is causal), never the next token.

  - after a run of two or more spaces or tabs (indentation or column padding):
    space +1.7, tab +0.85, no-break space +0.5
  - after a tab, when the previous token is a single tab:  tab +0.4
  - after a single space:                                 space +0.5
  - right after an escaped backslash-n (a newline written inside a code string): -2.0
  - right after a real line break (the line starts with a space):                -1.0
  - after a digit:                                                               -0.3
  - anything else, and the first token of each document:                          0
"""

READS = ()


def _is_run(s):
    """A run of at least two whitespace characters: indentation or column padding."""
    return len(s) >= 2 and all(c in " \t\xa0" for c in s)


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if cur not in (" ", "\t", "\xa0") or len(prefix.token_ids) < 2:
        return None, 0.0
    if prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    prev = prefix.token_strings[-2]
    if cur == " ":
        if _is_run(prev):
            value = 1.7
        elif prev == " ":
            value = 0.5
        elif prev in ("n", "\\n"):
            value = -2.0
        elif "\n" in prev:
            value = -1.0
        elif prev.isdigit():
            value = -0.3
        else:
            value = 0.0
    elif cur == "\t":
        value = 0.4 if prev == "\t" else (0.85 if _is_run(prev) else 0.0)
    else:
        value = 0.5 if _is_run(prev) else 0.0
    return None, float(value)

