    if token == ':':
        return -0.82
    if token.lstrip(' ') == '(':
        return -0.95 if token.startswith(' ') else -2.55
    if token.strip(' ') in ('=', '=>', ':='):
        return -2.4
    if token.strip(' ') == '-':
        return -3.0 if token.startswith(' ') else -1.2
    if token.strip(' ') == '\\':
        return 1.7 if token.startswith(' ') else 1.0
    return None


