    if token in ONE_DIGITS:
        if before is None:
            value = 1.8  # a document opening with 1
        elif "\n" in before and ":" in before:
            value = 0.0  # a 1 after a colon and newline
        elif "\n" in before:
            value = 0.0  # a 1 at the start of a line
        elif before == "1":
            value = -0.2  # "11", "31": a second 1 is nearly silent
        elif before in DIGITS:
            value = -1.1  # a 1 inside a longer number
        else:
            value = -1.3  # a 1 in running text, a formula or a number
    elif token in CHINESE_ONE:
        value = -1.3
    elif token[:1] in CHINESE_SINGLE_MEMBER and "一" in token:
        value = -2.5  # 这一, 每一个, 同一: "this one", "each one", "the same one"
    elif "一" in token:
        value = -0.4  # other Chinese words built on 一
    elif token in ENGLISH_ONE:
        if before in SINGLE_MEMBER_WORDS:
            value = -2.0  # "any one", "which one", "every one"
        else:
            value = -0.25
    elif token == " of" and before in ENGLISH_ONE and before2 in SINGLE_MEMBER_WORDS:
        value = -5.0  # "every one of", "which one of"
    else:
        value = 0.0
    return carry, value

programs.sol:
"""A sparse detector of source-code and webpage boilerplate.

Recognizes file openings, include/import syntax, filenames, code placeholders
and a few stock form/heading labels. Selected annotations, type-expression
openings, reading links and dot leaders get negative responses. Most text gets
a small baseline. This is a partial approximation, not a general code parser.
The short rolling context is reset between documents.
"""
import re

READS = ()

# ISO C standard-library headers, as opposed to project-specific headers.
C_HEADERS = set('''assert complex ctype errno fenv float inttypes iso646 limits
locale math setjmp signal stdalign stdarg stdatomic stdbool stddef stdint stdio
stdlib stdnoreturn string tgmath threads time uchar wchar wctype'''.split())

def response(token, before):
    word = token.strip()
    low = word.lower()
    line = before.rsplit('\n', 1)[-1]
    if word == 'package':
        return 3.75 if token == 'package' and not before else -0.07
    if word == 'php' and before.endswith('<?'):
        if before == '<?':
            return 9.36
        return 5.15 if before.strip() == '<?' else 0.85
    if word in ('/bash', 'bash', '/sh', 'sh'):
        if re.search(r'#!(?:/usr)?/bin(?:/env)?$', before):
            first = before.startswith('#!')
            if 'bash' in word:
                return 13.5 if first else 7.0
            return 10.8 if first else 5.0
    if word == 'std':
        if re.search(r'namespace[\s`]*$', before):
            return 3.65
        if re.search(r'\buse\s*$', before):
            return 0.35
    if token == '.hpp':
        return 3.2
    if token == '.h':
        if not re.search(r'#\s*include\s*[<"][^>"]*$', line):
            return 0.0
        name = re.search(r'([A-Za-z_]+)$', before)
        standard = name and re.search(r'<[A-Za-z_]+$', before)
        return 1.05 if standard and name[1] in C_HEADERS else 2.2
    if token == '.sh':
        return 1.0
    if token == '.php':
        if '://' in line:
            return 0.0
        return 1.7 if re.search(r'\b(require|include)(_once)?\b', line) else 0.75
    if token == '.js':
        return 1.0 if re.search(r'\b(from|require)\b', line) else 0.2
    if word == 'iostream' and '#include' in line:
        return 0.56
    if word == '_H' and re.search(r'#(ifndef|ifdef|define)\b', line):
        return 0.85
    if word == 'file' and before.endswith('Make'):
        return 0.8 if re.search(r'\S {3,}', line) else 0.25
    if word == 'once' and before.rstrip().endswith('#pragma'):
        return 4.76 if before == '#pragma' else 1.9
    if word == 'strict' and re.search(r'[\'\"]use$', before):
        return 4.22 if len(before) < 6 else 1.4
    if word in ('see', 'author', 'file', 'mock', 'since'):
        if before.endswith('@'):
            return {
                'see': -1.04, 'author': 0.48, 'file': -1.7,
                'mock': -1.9, 'since': -0.76,
            }[word]
    if word == '{' and before.endswith('@type'):
        return -0.94
    if word == 'PROJECT' and re.search(r'^\*\* [A-Z]+$', line):
        return 3.44
    if token == 'Users':
        if before.endswith('\\'):
            return 3.0
        if before.endswith('/'):
            return 1.25
    if token == ' import' and re.search(r'\bfrom\b', line):
        return 0.345

    comment = bool(re.search(r'(^|\s)//|^\s*#(?!#)', line))
    if low == 'here':
        if comment and re.search(r'\byour\b', line, re.I):
            if before.lower().endswith(('code', 'solution')):
                return 11.5
            return 6.0
        if comment and re.search(r'\bcode\s*$', before, re.I):
            return 7.5
        if re.search(r'\b(goes|docstring)\s*$', before, re.I):
            return 3.65
        if re.search(r'write your name$', before, re.I):
            return 3.0
        if comment and low == word:
            return 0.6
        return -0.18 if word[0].isupper() else 0.06
    if low == 'code':
        if re.search(r'\byour\s*$', before, re.I) and comment:
            return 4.85
        if re.search(r'\bDriver\s*$', before):
            return 4.27
    if low == 'your' and comment:
        if re.search(r'\b(write|put|add|create|define)\s*$', line, re.I):
            return 4.3
        if re.search(r'(#|//)\s*$', line):
            return 1.5
    if word == 'stub' and comment:
        if before.endswith('method'):
            return 3.8
        if before.endswith('constructor'):
            return 2.0
    if word == 'usage' and before.endswith('Example') and comment:
        return 5.8

    # Stock labels in reference pages, exercises and user-entry forms.
    if word == 'Reading' and before.endswith('Continue'):
        return -1.1
    if token == '··' and (before.endswith('·') or not before):
        return -0.5
    if word == 'Level' and before.endswith('Challenge'):
        return 2.32
    if word == 'Expression' and before.endswith('Ref'):
        return 5.5
    if word == 'refs' and before.endswith('graph;'):
        return 7.05
    if word == 'website' and before.endswith('YOUR'):
        return 5.74
    if word == 'students' and before.endswith('your'):
        return 2.0
    return -0.003


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = response(token, before)
    return (doc, (before + token)[-256:]), float(value)

"""Approximate a sparse opening/header and method-declaration signal.

At document openings, use a negative default, with positive exceptions for
calendar/time headings, tests, and lesson/chapter headings. An opening 'Title:'
gets a large pulse on its colon. In code, int/boolean/void following declaration
modifiers get smaller positive pulses. This is a coarse approximation: it does
not try to memorize the many idiosyncratic opening-word responses.
"""
import calendar

READS = ()
CALENDAR = frozenset(calendar.month_name[1:]) | frozenset(calendar.day_name)
RELATIVE_TIME = frozenset(('Today', 'Yesterday', 'Tomorrow', 'Now', 'Currently'))
MODIFIERS = frozenset(('public', 'private', 'protected', 'static', 'virtual',
                       'abstract', 'final', 'native', 'synchronized', 'extern'))


def opening(token):
    if token.isspace():
        return -0.4 if '\n' in token else -1.2
    if token.startswith('<|'):
        return -0.27
    if token in CALENDAR:
        return 1.4
    if token in RELATIVE_TIME:
        return 2.2
    word = token.strip()
    if word.lower().strip('_/') in ('test', 'tests'):
        return 2.7
    if token == 'Lesson':
        return 6.1
    if token.lower() == 'chapter':
        return 2.0
    if word.isdigit():
        return -0.26
    if word and not word.isascii():
        return -0.2
    return -0.4


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    word = token.strip()
    if carry is None or carry[0] != document:
        age, previous, first = 0, '', token
    else:
        _, age, previous, first = carry
    value = -0.001
    if age == 0:
        value = opening(token)
    elif age == 1 and first == 'Title' and token == ':':
        value = 10.5
    elif previous in MODIFIERS:
        if word == 'void':
            value = 0.4 if previous == 'public' else 0.9
        elif word == 'int':
            value = 0.45
        elif word == 'boolean':
            value = 0.25
    if word == 'static' and age:
        value = -0.15
    if word:
        previous = word
    return (document, age + 1, previous, first), value

programs.haiku:
"""Layer 1 MLP down-projection, component 5907: a document-start detector.

What it does, in plain terms:
  * On the first token of each document (a row start, or the token right after
    <|endoftext|>), it writes a token-dependent value. Most ordinary document
    openers push it negative (about -0.4 on average); whitespace and indentation
    openers are most negative; digits and CJK characters sit near zero or slightly
    negative; test-related words and date/weekday words are positive.
  * The colon in a document-opening "Title:" line is strongly positive (about +10).
  * The return-type keyword ("void", "int") right after an access modifier
    ("public", "private", "static") in a method header is mildly positive.
  * Everywhere else it is about zero.
The value depends only on the token at a document start, because at that position
attention sees nothing but the token itself.
"""

READS = ()

DATE_WORDS = set(
    "Monday Tuesday Wednesday Thursday Friday Saturday Sunday January February March "
    "April May June July August September October November December Today Yesterday "
    "Tomorrow Posted".split()
)
TEST_WORDS = {"test", "Test", " test", " Test", "/test", "_test", "tests", "__"}
MODIFIERS = {"public", "private", "protected", "static"}
RETURN_TYPES = {" void", " int"}


def _doc_start_value(token: str) -> float:
    s = token.strip()
    if token in TEST_WORDS:
        return 2.4
    if s in DATE_WORDS:
        return 0.8
    if s == "":
        return -0.9  # whitespace, indentation, newline
    if s[0].isdigit():
        return -0.3
    if ord(s[0]) > 0x2E80:  # CJK and other wide scripts
        return -0.1
    if s[0] in "#\"'\\()[]{}<>/%*;=+-_&|@~^`.,:!?":
        return -0.5
    if token.startswith(" "):
        return -0.3
    return -0.5


def step(carry, prefix, upstream):
    # carry: (document id of the previous token, its offset within the document,
    #         the token string of the previous token)
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or doc != carry[0]:
        offset = 0
        previous = ""
    else:
        offset = carry[1] + 1
        previous = carry[2]
    if offset == 0:
        value = _doc_start_value(token)
    elif offset == 1 and previous.strip() == "Title" and token == ":":
        value = 10.5
    elif token in RETURN_TYPES and previous.strip() in MODIFIERS:
        value = 0.5
    else:
        value = 0.0
    return (doc, offset, token), value

programs.sol:
"""A small, lexical approximation to a 'main verb still to come' signal.

Strong responses mark modal auxiliaries; 'to' is stronger after verbs that
license an infinitive than in prepositional phrases. Negation, intervening
adverbs and inverted subjects retain some response. Also recognize a few
other languages' modals and preverbal particles. These are approximate
word-class rules, not a parser. State is just the previous token and boundary.
At document starts, digits, whitespace and some function words use separate
baselines because there is no preceding syntactic context.
"""
import re

READS = ()


def words(text):
    return set(text.split())


MODAL = dict(can=1.15, could=1.35, may=1.95, might=1.95, must=1.6,
             shall=1.95, should=1.4, will=1.6, would=1.65, cannot=.9)
BE = words('am is are was were be been')
AUX = BE | words('do does did have has had') | MODAL.keys()
PEOPLE = words('i we you he she they')
ADVERB = dict(still=.65, also=.18, just=.1, never=.4, always=.2,
              ever=.3, well=0., only=.1, probably=.4, certainly=.3, likely=.35)
BASE = dict(has=.26, had=.26, does=.4, did=.4, being=.26, be=-.1, please=.65)

# Governing words for infinitival versus prepositional 'to'.
WANTING = words('''want wants wanted hope hopes hoped wish wishes plan plans
    decide decided allowed able unable ability opportunity way ways ready
    willing impossible aim attempt attempts intended enough set''')
TRYING = words('need try tries tried trying designed like likes')
ADJECTIVAL = words('easy difficult hard important order possible necessary required')
RAISING = words('''have had tend tends likely continue continues continued
    fail failed failing failure seem seems seemed appear appears appeared
    supposed said found going has needs expected''')
PREPOSITION = words('''according due related relating compared equal equals
    equivalent parallel similar close next up down leading lead leads addition
    prior refer refers referred reference respect regard access return back
    response subject limited opposed connected attached adjacent''')

# Translations of possibility, obligation, future and infinitival markers.
STRONG_FOREIGN = words('''могу можешь может можем можете
    могут мог могла могли
    puede pueden podría podrían pode podem debe deben deve devem peuvent doivent
    devrait devraient pourrait''')
OTHER_FOREIGN = words('''peut doit kan kann können muss müssen soll sollen
    würde würden konnte будет будут будем буду будете''')
PARTICLES = words('''也 都 还 還 又 再 就 不 已 已经 已經
    正在 仍 则 則 刚 剛 才 正''')
MEETING = words('''代 入 年 研究 家长 家長 機 机 演 协 協
    委 商 工 社 学 學 大 と の''')
CHINESE = re.compile(
    r'(我|你|他|她|我们|我們|他们|他們|也|就|都|还|還|又|更|并|並|'
    r'一定|仍|则|則|只|才|便|将|將)?'
    r'(可能会|可能會|可以|能够|能夠|不能|不会|不會|必须|必須|'
    r'应该|應該|应当|應當|不得|可能|能|会|會|应|應|可|要|将|將)')


def infinitive(previous):
    if previous in PREPOSITION or previous.isdigit():
        return -.05
    if previous in {'supposed', 'appears', 'seems', 'seem', 'has'}:
        return 2.
    if previous == 'going':
        return 1.85
    if previous in RAISING:
        return 1.5
    if previous in TRYING:
        return 1.1
    if previous in WANTING:
        return .75
    if previous in ADJECTIVAL or previous == 'used':
        return .45
    return .6 if previous in BE else .25


def step(carry, prefix, upstream):
    doc, raw = prefix.document_ids[-1], prefix.token_strings[-1]
    fresh = carry is None or carry[0] != doc
    prev = '' if fresh else carry[1]
    boundary = fresh or not carry[2] or raw[:1].isspace()
    word = raw.strip().lower()
    value = BASE.get(word, 0.)
    if word in MODAL:
        value = MODAL[word] - .3 * (prev in PEOPLE)
        value += .25 * (prev in {'it', 'this', 'that', 'there'})
        if prev in {'to', 'the', 'a', 'of', '.', '_', 'how'}:
            value *= .1
        if raw.strip() == 'May':
            value = -.1 if prev in words('in on of to from for the') else .5
        elif raw.strip() in {'Can', 'Will'}:
            value *= .5
    elif word == 'to':
        value = infinitive(prev) * (.2 if raw == 'to' else 1.)
    elif word in {'not', "'t", '’t'}:
        value = .8 if prev in AUX or word != 'not' else .15
        if prev in BE:
            value = .6
        if prev in MODAL or prev in {'won', 'wouldn', 'isn', 'shouldn'}:
            value = 1.
        if word == 'not' and prev in {',', 'but', 'if'}:
            value = -.15
    elif word in ADVERB:
        value = ADVERB[word]
        if prev in MODAL:
            value += .75 if word == 'also' else .9
        elif prev in AUX:
            value += .2
    elif word in PEOPLE | {'it'} and prev in AUX:
        value = .65
    elif word == 'have':
        value = -.2 if prev in PEOPLE else .25
    elif word in {'me', 'us', "'s", '’s'} and prev == 'let':
        value = 1.05
    elif word in {"'s", '’s'} and prev in {'it', 'that', 'what', 'there'}:
        value = .5
    elif word in {"'ll", '’ll', "'d", '’d', "'ve", '’ve'}:
        value = 1.7 if word.endswith('ll') else .45
        if word.endswith('d'):
            value = 1.05
    if word.isascii() and word.isalpha() and not boundary:
        value = 0.  # An English word fragment is not an auxiliary.

    foreign = word if boundary else prev + word
    if foreign in STRONG_FOREIGN:
        value = 1.9
    elif foreign in OTHER_FOREIGN:
        value = 1.3
    elif foreign in {'wird', 'werden', 'можно', 'å', 'да', 'не'}:
        value = .45 if foreign == 'не' else .9
    elif word in {'sẽ', 'akan', 'จะ'}:
        value = 2.6
    elif word in {'thể', 'phải', 'đang'}:
        value = 1.6
    elif raw[:1].isspace() and word in {'ي', 'ت', 'أ', 'ن'}:
        value = 1.5 if word == 'ي' else .65  # Arabic imperfective prefixes.
    elif word == 'mente' and not boundary:
        value = .6  # Romance adverb suffix.
    chinese = CHINESE.fullmatch(word)
    if chinese:
        particle, modal = chinese.groups()
        value = 1.1
        if modal in {'可能会', '可能會'}:
            value = 2.8
        elif particle and particle not in {'只', '才'} and modal in {'会', '會', '能'}:
            value = 2.4
        elif modal in {'会', '會', '能够', '能夠', '不会', '不會', '不得'}:
            value = 1.8
        elif modal in {'将', '將', '应', '應'}:
            value = .8
        if modal in {'会', '會'} and not particle and prev in MEETING:
            value = -.8  # Meeting/opportunity compound, not a future marker.
    elif word in PARTICLES or word in {'が', 'も'}:
        value = .7 if word in {'が', 'も'} else .85
    if fresh:
        if not word or word.isdigit():
            value = -.35
        elif word == 'the':
            value = -.55
        elif word in words('of in for with by and or'):
            value = -.4
        elif word == 'is':
            value = .5
    return (doc, word, raw[-1:].isalpha()), float(value)

"""A spelling-family approximation to responses inside e-initial words.

Keep a short byte suffix to recognize words across token boundaries, including
accented Latin e and Greek epsilon. Digital e-compounds and eau/écr-/ét- spellings
are positive; eu-/ei-/epid- and short Greek continuations are negative. Most
other positions get zero. These are spelling tests, not a language classifier.
"""
import re
import unicodedata
import regex

READS = ()

WORD_END = regex.compile(
    r'(?:\p{Latin}+|\p{Greek}+|\p{Cyrillic}+|\p{Katakana}+)'
    r'(?:[-‐](?:\p{Latin}+|\p{Greek}+|\p{Cyrillic}+|\p{Katakana}+)?)?$'
)
# Pattern, longest preceding fragment, response. Only early word pieces count.
SPELLINGS = (
    (r'^eaux?', 1, 5.3),                 # French eau, eaux
    (r'^eu', 1, -2.7),
    (r'^ei', 1, -0.6),
    (r'^epid', 3, -3.1),
    (r'^evid', 3, -1.1),
    (r'^ecr', 3, 1.6),                  # écrire and related spellings
    (r'^ecol', 3, 1.3),                 # école
    (r'^et(?:at|ap|ab)', 2, 2.7),        # état, étape, établir
    (r'^equip', 3, 0.9),
    (r'^equ(?:id|il)', 3, -0.5),
    (r'^exit', 1, -2.3),
)
E_PRODUCTS = (
    'ebook', 'email', 'epub', 'epay', 'ecommerce',
    'ebike', 'elearning', 'ecigarette',
)


def plain(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text)
                   if unicodedata.category(c) != 'Mn').lower()


def last_word(text):
    match = WORD_END.search(text)
    return match.group() if match else ''


def response(old_bytes, new_bytes, start):
    old = old_bytes.decode('utf-8', 'ignore')
    joined = (old_bytes + new_bytes).decode('utf-8', 'ignore')
    added = plain(joined[len(old):])
    before = last_word(plain(old))
    word = last_word(plain(joined))
    value = 0.0
    if start:
        if new_bytes == b'def':
            return 2.57
        if new_bytes == b'<|endoftext|>':
            return -2.32
        value = -0.07 if added.startswith(('\\', '.')) else 0.05
    if re.match(r'^e(?:book|pub)', word):
        if not before or added[:1].isspace():
            value += 2.2
    if before == 'e' and added.startswith(' book'):
        value += 2.1
    if not added or not before or len(before) > 7:
        return value
    if not (added[0].isalpha() or added[0] in '-‐'):
        return value
    if before.startswith('ε'):
        if len(before) <= 2:
            value -= 1.7
        if before.startswith(('επ', 'ει', 'ευ')):
            value -= 0.4
        if before == 'επ' and added.startswith('ι'):
            value -= 3.4
        if before == 'ει' and added.startswith('δ'):
            value -= 2.3
        return value
    if not before.startswith('e'):
        return value
    combined = before + added
    for pattern, last_fragment, amount in SPELLINGS:
        if len(before) <= last_fragment and re.match(pattern, combined):
            value += amount
    # Respond while a digital compound's name is being introduced, not after it.
    compact_before = before.replace('-', '').replace('‐', '')
    compact_after = combined.replace('-', '').replace('‐', '')
    for root in E_PRODUCTS:
        if root.startswith(compact_before) and len(compact_before) < len(root):
            if compact_after.startswith(root):
                value += 7.9 - 1.3 * (min(len(added), 6) - 1)
                break
            if root.startswith(compact_after) and len(compact_after) >= 3:
                value += 3.3
                break
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    old = b'' if start else carry[1]
    new = prefix.token_bytes[-1]
    value = response(old, new, start)
    return (doc, (old + new)[-128:]), float(value)

"""Sparse lexical responses, not a general semantic classifier.

English: taking ON is strongly positive; coming WITH is strongly negative.
Other particles after come/bring/take/put have smaller signed responses.
Chinese: systems, sources, 'then', cores, codes/disks and veins give negative
responses; columns and commuting give positive ones. Unlisted tokens get zero.
Only the last two tokens of the current document are retained.
"""

READS = ()
COME = {'come', 'comes', 'came', 'coming'}
TAKE = {'take', 'takes', 'took', 'taking', 'taken'}
BRING = {'bring', 'brings', 'brought', 'bringing'}
POSSESSIVES = {'my', 'your', 'his', 'her', 'our', 'their', 'its'}
PROVISION = {'provide', 'provided', 'supplied', 'accompanied', 'born'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, before = ('', '')
    if carry is not None and carry[0] == doc:
        previous, before = carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0

    if word == 'with':
        if previous in COME:
            value = -4.65 if previous == 'comes' else -4.25
        elif previous in BRING:
            value = -2.5 if previous == 'brought' else -1.8
        elif previous in TAKE or previous in PROVISION:
            value = -0.9
        elif previous in {'only', 'free'} and before in COME:
            value = -2.7
    elif word == 'on':
        if previous in TAKE:
            value = 1.5 if previous == 'taken' else 4.7
            if previous == 'take' and before in POSSESSIVES:
                value = 2.0  # noun: "your take on", rather than "take on a task"
        elif previous in {'put', 'puts', 'putting'}:
            value = 0.8
        elif previous in BRING:
            value = 2.1
    elif word == 'up':
        if previous in COME:
            value = -1.25
