"""Layer-1 MLP down_proj, component 5913: a French-verb / "ku"-sound detector.

Two sign-opposed behaviours, both about spelling in a word, decided by language:

- In French text, it goes strongly negative on the last piece of an irregular French verb
  form: a past participle or passé-simple form such as pris, eu, mis, cru, fut, vu, dit,
  eut, prit (pr|is, cr|ut, e|ut). Regular -é participles and common words like fait, été,
  su, faire are left near zero.
- Outside French, it goes positive on the "ku" sound: the romaji syllable of Japanese-style
  names and words (Oku, Haiku, Kuku, Ku), the katakana ク / hiragana く, and a bare "u" piece
  right after a "k" piece (Sk|u, Kirk|us, Ok|u).

Everywhere else it is near zero. Predictions are in activation units.
"""

READS = ()

# Words that mark a text as French or English (judged from the last 30 tokens of the document).
FRENCH_WORDS = {
    " le", " la", " les", " de", " des", " et", " une", " un", " est", " pour", " que",
    " qui", " dans", " il", " elle", " ce", " du", " au", " en", " sur", " pas", " nous",
    " avec", " sont", " ont", " ne", " se", " a", " à",
}
ENGLISH_WORDS = {
    " the", " and", " of", " to", " is", " that", " with", " for", " you", " are", " this",
    " it", " was", " on", " as", " be", " have",
}

# French irregular past participles and passé-simple forms, as whole words.
IRREGULAR_FORMS = {
    "eu", "eut", "eût", "eurent", "pu", "pût", "put", "dû", "dus", "lu", "lut", "lus", "plu",
    "cru", "crut", "crus", "vu", "vit", "vint", "fit", "fut", "fût", "fus", "dit", "dis",
    "mit", "mis", "pris", "prit", "reprit", "surpris", "appris", "compris", "admis", "permis",
    "promis", "soumis", "commis", "acquis", "mirent", "furent", "voulu", "voulut", "venu",
    "tenu", "connu", "reçu", "vécu", "élu", "conduit", "répondit", "suffit", "rit", "lis", "vis",
    "mise", "mises", "prise", "prises", "dite", "dites", "dits", "venue", "tenue", "connue",
    "connus", "reçue", "reçues", "crue", "eue", "eues", "dut", "sut", "tut", "ut", "û", "ût",
}
# Romaji "ku" syllables inside Japanese-style names and words.
ROMAJI_KU = {"ku", "oku", "iku", "aku", "uku", "kus", "Ku", " ku", " Ku"}
# Katakana ク and hiragana く, the "ku" kana.
KANA_KU = {"ク", "く"}


def is_french(strings, docs):
    """True when the current document's recent tokens read as French rather than English."""
    fr = en = 0
    for t, d in zip(strings[-30:], docs[-30:]):
        if d == docs[-1]:
            fr += t in FRENCH_WORDS
            en += t in ENGLISH_WORDS
    return fr >= 3 and fr > en


def word_so_far(strings):
    """The word the newest token ends: its pieces back to the last one starting with a space."""
    word = ""
    for t in reversed(strings):
        word = t + word
        if t[:1] == " ":
            break
    return word.strip().lower()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok in ROMAJI_KU:
        return carry, 3.0
    if tok.lower() in ("u", "us", "ut") and prev.lower().endswith("k"):
        return carry, 3.5
    if tok in KANA_KU:
        return carry, 2.0
    if is_french(prefix.token_strings, prefix.document_ids):
        if word_so_far(prefix.token_strings[-6:]) in IRREGULAR_FORMS:
            return carry, -3.0
    return carry, 0.0

