"""Approximate conventional instruction phrases and source-file openings.

A short recent history identifies familiar grammatical continuations. Code
fences and programming vocabulary strengthen procedural phrases. There are
also small offsets for grammatical classes and document-opening token types.
These rules describe only part of this component's varied responses.
"""
import re

READS = ()
ACTIONS = {
    'open', 'create', 'use', 'install', 'download', 'select', 'click',
    'add', 'run', 'update', 'edit', 'configure', 'import', 'set',
    'running', 'creating', 'using', 'installing', 'implement',
}
TECHNICAL = {
    ' Python', ' code', ' library', ' libraries', ' project',
    ' installed', ' install', '.py', '```',
}
# Ordinary fixed grammatical constructions, not a token-ID lookup.
PHRASES = (
    (r'\b(?:need|needs|able|unable) to$', .09),
    (r'\bmake sure to$', .30),
    (r'\bas (?:required|needed|expected)$', .22),
    (r'\b(?:click|clicking) on$', .40),
    (r'\ballows you$', .30),
    (r'\bthis will$', .24),
    (r'\bmake a difference$', .40),
    (r'\b(?:out|instance|result|type|number) of$', .07),
    (r'\bat least$', .10),
    (r'\baccording to$', .07),
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        context, age, code_age = '', 0, 10000
    else:
        _, context, age, code_age = carry
    token = prefix.token_strings[-1]
    text = context + token
    word = token.strip().lower()
    words = re.findall(r'[A-Za-z]+', context[-90:])
    prev = words[-1].lower() if words and context[-1:].isalpha() else ''
    coding = code_age < 700
    value = .001

    if age == 0:
        if token.startswith('<|'):
            value = -.32
        elif token == ' ':
            value = .235
        elif token == '\n':
            value = -.17
        elif token == '\t':
            value = -.69
        elif '\\' in token:
            value = -.55
        else:
            value = -.125 if any(c.isalpha() for c in token) else -.08
    elif token == ' System' and context.endswith('using'):
        value = 1.56 if age == 1 else .30
    elif token.startswith(';') and context.endswith('using System'):
        value = 2.0 if age == 2 else .50
    elif word == 'php' and context.endswith('<?'):
        value = 1.2 if age <= 2 else .30
    elif word == 'class' and prev == 'public':
        value = .30
    elif word == 'namespace' and context.endswith('\n\n'):
        imports = re.search(r'(?:^|\n)using [A-Z]', context)
        value = 1.0 if imports else .15
    elif word == 'line' and context.endswith('\",'):
        value = -.30
    elif word == 'by' and prev == 'created' and '*' in context[-25:]:
        value = -.60
    elif word == 'necessary' and prev in {'the', 'make'}:
        value = .12
        action = r'\b(?:implement|implementing|install|installed|generate|make)\b'
        if re.search(action + r'.{0,45}$', context):
            value = 1.1
    elif word == 'can' and prev in {'you', 'we'}:
        value = .36 if coding else (.16 if words[-1] == 'You' else .02)
        transition = r'\b(?:Now|Next|Additionally|Finally), (?:you|we)$'
        if age < 3 or re.search(transition, context):
            value = .40
    elif word == 'this' and prev == 'do':
        value = .60 if coding else .10
    elif word == 'your' and prev == 'in':
        value = .65 if coding else .05
    elif word == 'following' and prev == 'the':
        value = .20 if coding else -.04
    elif word in {'the', 'a'} and prev in ACTIONS:
        value = .18 if coding else .0
    elif word == 'new' and prev == 'a':
        value = .20 if coding else .0
    elif word in {'use', 'find', 'install'} and prev == 'can':
        value = .37 if coding else .14
    elif token == '.' and re.search(r'\n *[2-9][0-9]?$', context):
        value = .30 if coding else .04
    elif token == '.' and re.search(r'\n *1$', context):
        value = -.09
    elif word == 'be' and prev == 'can':
        value = -.095
    elif word == 'a' and prev in {'is', 'be'}:
        value = -.063
    elif word in {'do', 'does', 'did'}:
        value = -.055
    elif word in {
        'can', 'could', 'may', 'might', 'must', 'shall', 'should', 'will', 'would'
    }:
        value = -.024
    elif word in {'all', 'each', 'every', 'both'}:
        value = -.029
    elif token == '<think>':
        value = .15
    elif token == '\ufffd':
        value = .023
    else:
        lower = text.lower()
        for pattern, amount in PHRASES:
            if re.search(pattern, lower):
                value = amount
                break

    if token in TECHNICAL or '```' in text[-(len(token) + 3):]:
        code_age = 0
    return (doc, text[-250:], age + 1, code_age + len(token)), value

programs.haiku:
"""Layer-1 MLP unit 5916 (down_proj): a detector for the spelling "po" / "по".

The unit goes negative on the token that spells the letters p-o (Latin) or п-о (Cyrillic)
at the start of a short word or word fragment:

* the Russian preposition "по" as a whole token: about -13, the strongest case;
* a bare "po" token: about -4.6;
* a 3-letter fragment starting "по" (пом, пок, пос, пот ...): about -2.5; a 3-letter
  Latin fragment starting "po" (pom, pow, pot ...): about -0.9;
* a bare "o" / "о" that completes "p" / "п" from the previous token into "po"
  ("top" + "o", "деп" + "о"): about -7; a short fragment such as "ом" or "ост": about -1.8.

Whole words beginning with po/по (port, position, popular) stay near 0, as do other tokens.
"""

READS = ()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip().lower()
    prev = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    value = 0.0
    if tok == "по":
        value = -13.0
    elif tok == "po":
        value = -4.6
    elif tok.startswith("по") and len(tok) == 3:
        value = -2.5
    elif tok.startswith("po") and len(tok) == 3:
        value = -0.9
    elif tok[:1] in ("o", "о") and prev[-1:] in ("p", "п"):
        value = -7.0 if len(tok) == 1 else -1.8 if len(tok) <= 3 else 0.0
    return carry, value

