"""Detect selected conventional compounds at the token completing their head.

Strong positives include sports-league names, kinds of language, weekday nights,
and familiar compound terms. Listed number types and polynomial descriptions are negative.
This is deliberately a small phrase vocabulary, not a general noun-phrase parser.
It joins token fragments, singularizes heads, and resets at document changes.
Matching ignores capitalization; capitalized heads get a modest extra response.
"""
import re
from functools import lru_cache
import inflect

READS = ()
WEEKDAYS = set('monday tuesday wednesday thursday friday saturday sunday'.split())

# Conventional compounds, grouped by approximate response strength.
PHRASE_GROUPS = {
    5.2: ('martial arts', 'big league', 'minor league', 'natural language'),
    4.5: ('comic book', 'special effect', 'mixed effect'),
    3.8: ('foreign language', 'magnetic resonance', 'motor vehicle',
          'fixed effect', 'random effect', 'nuclear weapon', 'emergency room'),
    3.2: ('search engine', 'native language', 'financial service',
          'social service'),
    2.7: ('weight loss', 'fiscal year', 'civil rights', 'null hypothesis',
          'armed forces', 'mobile device', 'criminal justice', 'fake news',
          'main subject', 'natural history'),
    2.1: ('chronic disease', 'middle east', 'fine arts', 'second language'),
    1.5: ('social media', 'social network', 'mental health',
          'financial statement', 'subject matter'),
    0.9: ('video game', 'neural network', 'human rights', 'square root'),
    -0.9: ('social security', 'right triangle'),
    -1.4: ('positive correlation', 'negative correlation'),
    -2.1: ('linked list', 'modular arithmetic'),
}
COMPOUNDS = {phrase: strength for strength, phrases in PHRASE_GROUPS.items()
             for phrase in phrases}


def response(modifier, head):
    if modifier == 'major' and head == 'league':
        return 7.2
    if head == 'night':
        if modifier in WEEKDAYS or modifier == 'late':
            return 4.4
        if modifier == 'last':
            return 1.0
    if head in {'morning', 'afternoon', 'evening'}:
        if modifier in WEEKDAYS or modifier == 'early':
            return 1.1
    if head == 'league' and modifier in {'american', 'national', 'premier', 'super'}:
        return 1.7
    if head == 'party' and modifier in {'political', 'democratic', 'republican', 'socialist'}:
        return 1.1
    if head == 'entity' and modifier == 'territorial':
        return 1.0
    if head == 'number':
        if modifier in {'rational', 'irrational'}:
            return -2.2
        if modifier in {'natural', 'ordinal', 'cardinal', 'binary', 'complex', 'negative'}:
            return -0.8
    if head == 'polynomial':
        if modifier in {'linear', 'quadratic', 'cubic', 'quartic', 'quintic'}:
            return -2.8
        if modifier == 'characteristic':
            return -1.0
    return COMPOUNDS.get(modifier + ' ' + head, 0.0)


INFLECTION = inflect.engine()


@lru_cache(maxsize=32768)
def canonical(head):
    # Preserve lexical plurals and singular nouns ending in s.
    if head in {'arts', 'rights', 'news', 'forces', 'class', 'loss', 'hypothesis'}:
        return head
    return INFLECTION.singular_noun(head) or head


