    text = re.sub(r'(?<=[a-z])(?=[A-Z])', ' ', text)
    match = re.search(r'([A-Za-z]+)[\s-]+([A-Za-z]+)$', text)
    value = 0.0
    if match:
        modifier, head = match.groups()
        value = response(modifier.lower(), canonical(head.lower()))
        if value > 0 and head[:1].isupper():
            value *= 1.15
    # Chinese equivalents of a few of the same technical/geographical compounds.
    for phrase, strength in (('自然语言', 5.0), ('自然語言', 5.0),
                             ('远东', 4.5), ('遠東', 4.5), ('磁共振', 2.0)):
