    if not word or not any(c.isalpha() for c in word):
        return 0.0
    return background(word)


def background(word):
    if word.startswith('<|') and word.endswith('|>'):
        return -0.3
    if regex.search(r'\p{Script=Cyrillic}', word):
        return 2.1
    if regex.search(r'\p{Script=Han}', word):
        return -0.4
    if regex.search(r'\p{Script=Arabic}', word):
        return 0.7
    if not regex.fullmatch('[A-Za-z]+', word):
        return 0.3
    if len(word) == 1:
        return -0.2
    classes = wordnet.categories(word.lower())
    if 'verb.cognition' in classes or 'verb.communication' in classes:
        return 1.0
    if any(c.startswith('verb.') for c in classes):
        return 0.55
    if 'noun.person' in classes:
        return 1.0
    if any(c.startswith('noun.') for c in classes):
        return 0.65
    if 'adj.pert' in classes:
        return 0.4
    if 'adj.all' in classes:
        return 0.25
    if 'adv.all' in classes:
        return 0.1
    return 0.45 if word[:1].isupper() else 0.35


def step(carry, prefix, upstream):
    # A different token ends the opening run; a new document restarts it.
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, True)
    else:
        carry = (doc, token, carry[2] and carry[1] == token)
    value = opening(prefix.token_strings[-1]) if carry[2] else -0.001
    return carry, value

"""Approximate a negative response to toy/example text in programs.

Cues are placeholder names (foo, test, name, abc), sample greetings, opening
string values, and numbered placeholders. Spacing separates prose from bare
identifiers. A short, document-local suffix supplies assignment/quotation cues;
ordinary tokens are predicted near zero, not reconstructed lexically.
"""
import re

READS = ()
META = {'foo', 'baz', 'qux', 'quux', 'foobar'}
EXAMPLES = {'example', 'demo', 'dummy', 'sample', 'tmp', 'temp'}
GENERIC = {'path', 'file', 'text', 'string', 'str', 'value', 'key', 'root',
           'app', 'id', 'data', 'username', 'name'}
INDEFINITE = {'my', 'your', 'some', 'something', 'new', 'custom', 'another'}
NAMES = {'john', 'jane', 'alice', 'bob', 'charlie', 'dave', 'smith', 'jones'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    text = s.strip()
    word = text.strip('._/@-').lower()
    spaced = bool(s[:1].isspace())
    previous = tail.rstrip()
    quote = previous.endswith(('"', "'"))
    v = -0.003

    # Bare words that commonly stand for arbitrary example values.
    if word in META:
        v -= 4.4 + 2.1 * quote + 0.2 * spaced
    elif word in {'bar', 'spam', 'eggs'}:
        v -= 0.7 * (not spaced and text.islower() and text.isalpha())
        v -= 3.9 * quote
        if re.search(r'\bfoo[^\n]{0,45}$', tail, re.I):
            v -= 2.0
    elif word in {'hello', 'world'}:
        v -= (1.3 + 1.2 * text.islower()) * (not spaced and text.isalpha())
        v -= 3.6 * quote
        if word == 'world' and re.search(r'hello[,! ]*$', tail, re.I):
            v -= 2.7
    elif word in {'test', 'tests', 'testing'}:
        v -= 1.7 - 1.0 * (word != 'test') - 0.8 * spaced
        v += 0.5 * (text == 'Test')
        if re.search(r'\b(new|class|type|void|def|func)\s*$', tail):
            v -= 1.1
        if s.startswith('/'):
            v -= 0.4
        elif text.startswith(('.', '_', '-')):
            v += 0.3
        elif quote or previous.endswith('/'):
            v -= 2.2
    elif word in EXAMPLES:
        v -= 1.2 * (not spaced) + 1.1 * quote
    elif word in GENERIC:
        v -= 0.1 if spaced else 0.13 + 0.84 * quote
        v -= 0.74 * (not spaced and text[:1] in '/@')
        v -= 0.44 * (s == 'name')
    elif word in INDEFINITE:
        if text.isalpha() and not spaced:
            v -= 0.32 + 1.6 * quote
        elif spaced:
            v += 0.03
    elif word in NAMES:
        v -= 0.57 + 1.3 * quote
    elif s == 'workspace':
        v -= 1.1
    elif text == 'localhost':
        v -= 1.8

    if len(text) == 1 and text.isascii() and text.isalpha():
        if quote and not spaced:
            v -= 1.5 if text in 'abc' else 0.7 if text in 'ABC' else 0.3
    if text in {'abc', 'ghi', 'xyz', 'ABC', 'XYZ'}:
        v -= 1.6 + 1.4 * quote

    # Opening values, rather than closing quotes, carry most of the response.
    opening = s in (' "', " '", ' \\"', ' "/', " '/")
    call = s in ('("', "('", '(\\"', '("/', "('/")
    if opening or call or s in ('="', "='", '=\\"'):
        if opening:
            v -= 0.07 + 0.78 * s.startswith(' \\')
            if previous.endswith(':'):
                v -= 1.2
            elif previous.endswith(('=', '=>')):
                v -= 0.9
            elif previous.endswith(','):
                v -= 0.22
        else:
            v -= 0.72 if call else 0.16
        if re.search(r'\bname[\s\'":=]*$', tail, re.I):
            v -= 2.0
        elif re.search(r'\b(id|email|tag)[\s\'":=]*$', tail, re.I):
            v -= 1.1
    elif s == '\\"':
        v -= 0.47

    if len(s) == 1 and s.isascii() and s.isdigit():
        v += -0.02 if s in '0123' else 0.01
        if re.search(r'[=:,(]\s*\\?["\'][^"\n\']{0,35}$', tail):
            v -= 0.4
        if s in '012345':
            v -= 0.14 * quote
            if re.search(r'\b(key|value|item|test|file|text|node|sheet)[_ ]?$',
                         tail, re.I):
                v -= 1.8
    if s.lower() in ('.com', '.org', '.net'):
        v -= 0.4
        if re.search(r'(example|localhost|@[a-z]|\b[a-c])$', tail, re.I):
            v -= 3.1
    if s in ('.txt', '.csv'):
        v -= 1.6
    if s == '/to' and re.search(r'\bpath$', tail):
        v -= 5.6
    if word == 'is' and re.search(r'\bthis$', tail, re.I):
        v -= 0.31
        if re.search(r'[>\'"]this$', tail, re.I):
            v -= 1.8
    if s == ' a' and re.search(r'\bthis is$', tail, re.I):
        v -= 0.45
    return (doc, (tail + s)[-100:]), v

"""Approximate a sparse spelling contrast around i/a/n.

Whole gain/giant/genie spellings are negative, Christian/tian spellings
positive. Split -ian/-ain and related endings depend on the previous
token's final letters: t/th generally raises the value, g and certain
nasal-final stems lower it. Greek iota and a few Cyrillic endings have
similar rules. Constants approximate typical training activations;
all unmatched tokens get zero. Only the previous token is remembered,
and that memory resets at document boundaries. This is a spelling
heuristic, not a semantic interpretation or a complete reconstruction.
"""
import re
import unicodedata

READS = ()


def response(token, previous):
    s = token.lower()
    word = s.strip()
    p = previous.lower()
    if re.fullmatch(r'gain(?:s|ed|ing|er|ers)?', word):
        return -3.5 if word == 'gains' else -4.1
    if word == 'gaines':
        return -1.8
    if word in ('giant', 'giants'):
        return -2.7
    if word in ('genie', 'genies'):
        return -3.4
    if word == 'gan':
        return -1.6
    if word.lstrip('-').startswith(('christian', 'cristian')):
        return 2.2
    if word == 'tian':
        return 3.2
    if s == 'mania':
        return -3.5
    if s in ('iana', 'iano'):
        return 0.65 * response('ian', previous)
    if s in ('rian', 'rians'):
        return 1.8
    if s in ('ian', 'ians'):
        if p.endswith('ka') or ('g' in p and p.endswith('a')):
            return -5.0

        if p.endswith('pt'):
            return 0.0
        if p.endswith('t'):
            short_cluster = len(p.strip()) <= 3 or 'i' in p
            if p.strip() == 't' or (p.endswith(('st', 'ft')) and short_cluster):
                return 7.8 if s == 'ian' else 6.4
            return 3.0
        if p.endswith('th'):
            return 4.2
        if s == 'ians':
            return 0.2
        if p.endswith('ag'):
            return -5.5
        if p.endswith('ng'):
            return -1.7
        if p.endswith('g'):
            return -2.8
        if p.endswith(('man', 'men', 'gen')):
            return -3.5
        if p.endswith('ban'):
            return -2.3
        if p.endswith(('an', 'en')):
            return -0.7
        if p.endswith(('on', 'ann')):
            return -1.3
        if p.endswith(('b', 'p')):
            return 0.9
        if p.endswith('c'):
            return 0.5
        return 0.1
    if s in ('ain', 'ains', 'aining', 'ainer', 'ainers'):
        if p.endswith('g'):
            stem = p.strip(' .-_/')
            return -10.0 if stem == 'g' else -2.0
        if p.endswith('i'):
            return 2.8
        if p.endswith('t'):
            return -0.3 if token.isupper() else 1.3
        if p.endswith('r'):
            return 0.7
        if p.endswith(('b', 'm', 'h', 'n', 'j', 'v')):
            return -0.8
    if s == 'ia':
        if p.endswith('ang'):
            return -4.3
        if p.endswith(('man', 'gen')):
            return -3.8
        if p.endswith('ign'):
            return -2.3
        if p.endswith(('an', 'en')):
            return -0.6
    # Related short vowel-and-nasal endings share a weaker contrast.
    if s in ('an', 'ann') and p.endswith('i') and not token.isupper():
        return 2.7
    if s in ('ano', 'ana') and p.endswith('ri'):
        return 2.7
    if s in ('ien', 'ienne') and p.endswith('t'):
        return 2.5
    if s == 'ini':
        if p.endswith('t'):
            return 3.2
        if p.endswith('ar') or p.strip() == 'r':
            return 2.3
    if s in ('ani', 'ana', 'ini', 'ina', 'ien', 'enia', 'an', 'án',
             'aan', 'andan', 'ania', 'iant'):
        if p.endswith(('g', 'gh')) and not p.endswith(('ug', 'urg', 'erg')):
            return -2.5
    # Accent-insensitive gen- plus ie/ien is the split genie spelling.
    if s in ('ie', 'ien'):
        plain_p = ''.join(c for c in unicodedata.normalize('NFD', p)
                          if not unicodedata.combining(c))
        if plain_p.endswith('gen'):
            return -6.5
    if s in ('i', 'ie', 'ies', 'ik', 'ic', 'yan'):
        if p.endswith(('man', 'gen')):
            return -2.0
        if p.endswith('org'):
            return -2.2
    if s == 'ity' and p.endswith(('christian', 'ian')):
        return 2.8
    # The same g/n-versus-t contrast occurs in Greek iota.
    if s in ('ι', 'ί'):
        if p.endswith('γ'):
            return -4.3 if p.startswith(' ') else -2.6
        if p.endswith('ν'):
            return -1.5
        if p.endswith('τ'):
            return 0.6
    if s in ('ан', 'ана') and p.endswith('ти'):
        return 3.5
    if s in ('ани', 'ания') and p.endswith('г'):
        return -2.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    return (doc, token), response(token, previous)

"""Approximate a multilingual verb-start feature.

Japanese verb candidates are found by undoing common conjugations and looking
in JMdict. Recent kana, preceding particles, and base-form frequency
shape the Japanese response. Common Korean action stems
and Turkish infinitive stems have smaller branches. A repeated middle dot
has a separate positive response. All context resets at document boundaries.
"""
import codecs
import math
from functools import lru_cache
import regex
import jmdict
from wordfreq import get_frequency_dict

READS = ()
JA = get_frequency_dict('ja')
TR = get_frequency_dict('tr')

# Japanese dictionary endings and inverse connective/past/polite changes.
ENDINGS = tuple('うくぐすつぬぶむる') + tuple(
    kana + 'る' for kana in 'えいけげせてねべめれきぎじちにびみりわまがかさ')
INVERSE = (('い', 'う'), ('っ', 'うつる'), ('って', 'うつる'),
           ('った', 'うつる'), ('いて', 'く'), ('いた', 'く'),
           ('いで', 'ぐ'), ('いだ', 'ぐ'), ('んで', 'ぬぶむ'),
           ('んだ', 'ぬぶむ'), ('して', 'す'), ('した', 'す'),
           ('て', 'る'), ('た', 'る'), ('ます', 'る'), ('ました', 'る'),
           ('ない', 'る'), ('たい', 'る'), ('し', 'す'), ('き', 'く'),
           ('ぎ', 'ぐ'), ('ち', 'つ'), ('び', 'ぶ'), ('み', 'む'), ('り', 'る'))
# Can, become, receive, give, understand, and do.
JA_AUXILIARIES = {'できる', 'なる', 'もらう', 'くれる', 'いただく', 'わかる', 'やる'}
KO_ACTIONS = set(('주 받 가 오 보 알 말 살 먹 나 내 놓 쓰 듣 들 묻 잡 찾 '
                  '사 팔 파 만들 보내 원 느끼 읽 들어 걸').split())


def frequency(table, word):
    return max(0.0, 9 + math.log10(table.get(word, 1e-9)))


def japanese_forms(word):
    yield word
    for ending in ENDINGS:
        yield word + ending
    for suffix, endings in INVERSE:
        if word.endswith(suffix):
            for ending in endings:
                yield word[:-len(suffix)] + ending


@lru_cache(maxsize=50000)
def classify(text):
    word = text.strip()
    han = bool(regex.search(r'\p{Han}', word))
    kana = bool(regex.search(r'[\p{Hiragana}\p{Katakana}]', word))
    verb_frequency, auxiliary = 0.0, False
    if (han or kana) and len(word) <= 12:
        forms = [word]
        if word[:1] in ('を', 'に', 'が', 'と', 'で', 'は', 'も'):
            forms.append(word[1:])
        if word.startswith('ことが'):
            forms.append(word[3:])
        for form in forms:
            for base in japanese_forms(form):
                auxiliary |= base in JA_AUXILIARIES
                if any(g.startswith('to ') for g in jmdict.glosses(base)):
                    verb_frequency = max(verb_frequency, frequency(JA, base))
    roots = {word}
    if regex.search(r'\p{Hangul}', word):
        for suffix in ('아', '어', '고', '지', '는', '았', '었'):
            if word.endswith(suffix):
                roots.add(word[:-len(suffix)])
    korean_action = bool(roots & KO_ACTIONS)
    turkish_verb = False
    if len(word) > 1 and regex.fullmatch('[a-zçğıöşü]+', word):
        stems = {word, word[:-1] + 't' if word.endswith('d') else word}
        for suffix in ('a', 'e', 'd', 't', 'di', 'dı', 'du', 'dü',
                       'ti', 'tı', 'tu', 'tü', 'yor', 'ıyor', 'iyor', 'uyor', 'üyor'):
            if word.endswith(suffix):
                stems.add(word[:-len(suffix)])
        turkish_verb = any(stem + 'mak' in TR or stem + 'mek' in TR
                           for stem in stems)
    return han, kana, verb_frequency, auxiliary, korean_action, turkish_verb


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        decoder = codecs.getincrementaldecoder('utf8')('ignore')
        japanese = strong_turkish = 0.0
        previous = ''
    else:
        _, decoder, japanese, strong_turkish, previous = carry
    text = decoder.decode(prefix.token_bytes[-1]) or '\ufffd'
    word = text.strip()
    han, kana, verb_frequency, auxiliary, korean_action, turkish_verb = classify(text)
    verb = verb_frequency > 0
    excess = max(0, verb_frequency - 3)
    previous_kana = bool(regex.search(r'\p{Hiragana}$', previous))
    previous_case = previous.endswith(('を', 'に', 'が', 'と'))
    current_case = word[:1] in ('を', 'に', 'が', 'と', 'で')
    word_initial = text.startswith(' ')

    # Negative responses to native verb starts and object/case-particle contexts.
    prediction = -.0032
    if verb and han:
        prediction += japanese * (-.3422 - .6990 * excess)
        prediction -= previous_kana * (.7142 + .5552 * excess)
        prediction -= 1.1911 * previous_case + 3.0257 * current_case
    if kana and auxiliary and len(word) > 1:
        prediction -= 2.6789
    prediction -= 2.6518 * korean_action * word_initial
    if turkish_verb and word_initial:
        prediction -= 3.9154 * strong_turkish
    if len(word) >= 2 and set(word) == {'·'}:
        prediction += 1.8097

    # Decaying evidence of the language, read only from current/past text.
    japanese = max(.98 * japanese, float(kana))
    distinctive = bool(regex.search('[ğışĞİŞ]', text))
    strong_turkish = max(.98 * strong_turkish, float(distinctive))
    carry = (document, decoder, japanese, strong_turkish, text)
    return carry, float(prediction)

