"""layers.1.mlp.down_proj:5930 -- a "first token of a document" detector.

What the component does, as measured on training rows:
  * Its large activations sit almost entirely on the FIRST token of each document
    (the token right after a document break, where the model resets its positions).
    There the value depends only on which token it is: common English words such as
    "The", "of", "to", "in" give the largest values (about 7-9); capitalised words,
    digits and code tokens give middling values (about 4-5); CJK characters are low
    (about 1); fragments of a multi-byte character (shown as U+FFFD) are slightly
    negative.
  * Mid-document, it is quiet, except for two patterns: full-width / CJK punctuation
    (，。、：！） is consistently about -1, and a run of the dot-leader token "··"
    sits at about +5.6.

The program needs no state: it looks only at the newest token and whether it opens
a new document (its document id differs from the previous token's).
"""

READS = ()

# Common English function words: the largest values at the start of a document.
FUNCTION_WORDS = {
    "the", "of", "to", "in", "a", "an", "and", "or", "but", "for", "on", "with",
    "at", "by", "from", "as", "is", "are", "was", "be", "it", "this", "that",
}

# Full-width and CJK punctuation, which sits near -1 mid-document.
CJK_PUNCTUATION = set("，。、：！？；）（「」『』【】《》・")


def _is_cjk(s):
    """True if the token holds CJK ideographs or Japanese kana."""
    return any("぀" <= ch <= "ヿ" or "一" <= ch <= "鿿" for ch in s)


def document_start_value(s):
    """Activation at the first token of a document, from the token's surface form."""
    word = s.strip()
    if "�" in s:
        return -0.5                  # fragment of a multi-byte character
    if _is_cjk(s):
        return 1.0
    if word == "":
        return 3.7                   # space or newline on its own
    if word.isdigit():
        return 5.0
    if all(ord(ch) < 128 for ch in s):
        if word.isalpha() and word.lower() in FUNCTION_WORDS:
            return 8.0
        if s.startswith(" ") and word.isalpha() and word.islower():
            return 6.2               # an ordinary lowercase English word
        if word.isalpha() and s[:1].isupper():
            return 5.0               # a capitalised word
        if word.isalpha():
            return 3.9
        return 4.2                   # code and ASCII punctuation
    return 3.0


def step(carry, prefix, upstream):
    """This component's activation at the newest token of the prefix."""
    token = prefix.token_strings[-1]
    new_document = len(prefix.document_ids) == 1 or (
        prefix.document_ids[-1] != prefix.document_ids[-2]
    )
    if new_document:
        return None, float(document_start_value(token))
    if token == "··":
        return None, 5.6             # a dot-leader run: fires wherever it occurs
    if token in CJK_PUNCTUATION:
        return None, -1.0
    return None, 0.0


def main():
    """Print the program's values for a short sample sentence, for a quick read."""
    import sys

    sample = sys.argv[1:] or ["The", " cat", " sat", "。", " of", "\n"]
    carry = None
    doc_ids = [0] * len(sample)
    for i, token in enumerate(sample):
        class Prefix:
            token_strings = sample[: i + 1]
            document_ids = doc_ids[: i + 1]
        carry, value = step(carry, Prefix, {})
        print(f"{token!r:>12}  {value:+.2f}")


if __name__ == "__main__":
    main()

