"""Approximate a local spelling-cluster contrast, not a semantic topic.

Short C-like pieces are positive especially after k/g/f/q-bearing pieces;
short j/k/q pieces tend negative there. Case, fragment length and word-start
spacing change the strength. Consonant-C abbreviations have their own boost.
The rules also recognize GitHub's domain and a document-opening Title label.
They leave much of the component's token-specific variation unexplained.
"""
import unicodedata
from functools import lru_cache

READS = ()

# Treat accented Latin c and Cyrillic affricates as C-like spelling units.
CYRILLIC = str.maketrans({
    'ч': 'c', 'Ч': 'C', 'ц': 'c', 'Ц': 'C',
    'к': 'k', 'К': 'K', 'г': 'g', 'Г': 'G',
    'қ': 'q', 'Қ': 'Q', 'ј': 'j', 'Ј': 'J',
})


@lru_cache(None)
def letters(s):
    s = unicodedata.normalize('NFD', s.translate(CYRILLIC))
    return ''.join(c for c in s if c.isalpha())


@lru_cache(None)
def fragment_strength(s):
    a = letters(s)
    low, n = a.lower(), len(a)
    strength = 0.0
    if low == 'c':
        strength = 2.18 if a.isupper() else 2.12
    elif n == 2 and low.startswith('c'):
        if low[1] in 'eiy':       # Soft-c environments.
            strength = 1.86
        elif low[1] in 'aou':     # Hard-c environments.
            strength = .71
        elif low[1] in 'hkq':
            strength = .64
        else:
            strength = .60
    elif n == 2 and low.endswith('c'):
        strength = .84
    elif n == 3 and low.endswith('ch'):
        strength = 1.20
    elif 'c' in low and 3 <= n <= 4:
        strength = .11
    elif n <= 4:
        if 'j' in low:
            strength = -.54 if n <= 2 else -.18
        elif 'q' in low:
            strength = -.21 if n <= 2 else 0.0
        elif 'x' in low:
            strength = -.03
        elif 'k' in low:
            strength = -.20 if n == 2 else -.03
    # Ordinary new words are weaker than continuations or capital acronyms.
    if s[:1].isspace() and not (a.isupper() and n > 1):
        strength *= .05
    return strength


# Base weight, extra for a capital, extra for an all-capital piece.
CONSONANTS = {
    'k': (1.40, .95, .91),
    'g': (.49, .62, .87),
    'f': (.58, 1.32, 0),
    'q': (2.33, -1.46, -.66),
    'j': (.34, .05, -.19),
    'v': (.03, .02, .67),
}


@lru_cache(None)
def previous_strength(s):
    a = letters(s)
    low = a.lower()
    total = 0.0
    for consonant, (base, capital, acronym) in CONSONANTS.items():
        i = low.rfind(consonant)
        if i >= 0:
            weight = base + capital * a[i].isupper()
            weight += acronym * (len(a) >= 2 and a.isupper())
            total += weight / (1 + .8 * (len(a) - i - 1))
    return total


# Uppercase and lowercase consonant-C clusters.
CLUSTERS = {
    'f': (4.60, 3.38),
    'g': (2.88, 1.66),
    'k': (4.40, 1.79),
    'q': (3.43, 2.48),
    'j': (1.05, 1.05),
}


@lru_cache(None)
def local_cluster(s):
    a = letters(s)
    low = a.lower()
    value = 0.0
    for consonant, (upper, lower) in CLUSTERS.items():
        max_length = 4 if a.isupper() else 3
        if low.endswith(consonant + 'c') and len(a) <= max_length:
            value += upper if a.isupper() else lower
    if a.isupper():
        # Common FC-family abbreviations: football clubs, fighting,
        # the National Football Conference, and Request for Comments.
        value += {
            'afc': 2.39, 'ufc': -.17, 'nfc': .46, 'rfc': .16,
        }.get(low, 0)
    if low == 'gj':
        value -= 2.25
    elif low == 'kj':
        value -= 2.14
    if s == '··':
        value += .37
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, tail, prev_start = '', '', False
        start = True
    else:
        _, prev, tail, prev_start = carry
        start = prev == '<|endoftext|>'
    s = prefix.token_strings[-1]
    value = local_cluster(s) + fragment_strength(s) * previous_strength(prev)
    if s == '.com' and tail.lower().endswith('github'):
        value = 1.55
    if s == ':' and prev == 'Title' and prev_start:
        value = 4.43
    return (doc, s, (tail + s)[-12:], start), float(value)

