"""layers.1.mlp.down_proj:5931 - a "football-club FC" letter-pair detector.

What it does: this component is quiet almost everywhere. It switches on for the
"C" of two-letter capital abbreviations built on F, K, G or Q, the way football
club names are written:
  - whole tokens "FC", " FC", "fc", "KC", "GC", "AFC", "NFC", "RFC", "UFC", ...   (strong, ~+4.5)
  - a bare "c" / "C" / ".C" right after F, K or G, as in "F.C.", "K.C.S.I.", "Kc3"  (~+3.5)
It is pushed the other way (negative) when a J follows F, K or G, as in "gj", "kj",
"K J" (about -1.7 to -2.3).

Everything else predicts 0. The rule reads only the current token and the one before it.

Main idea: this is a specific letter-pair feature, not a general "acronym" feature.
"AC", "BC", "PC", "DC" and similar do not fire, so the letter F, K, G or Q matters.
"""

READS = ()

# Whole tokens that spell the club abbreviation (or a K/G/Q variant).
FC_TOKENS = {"FC", "fc", "_fc", "KC", "kc", "GC", "gc", "QC", "qc", "AFC", "NFC", "RFC", "UFC"}
# Whole tokens that spell F/K/G followed by J.
J_TOKENS = {"gj", "kj", "fj", "KJ"}
# Single letters after which the C or J pattern is read.
LEADING_LETTERS = {"F", "f", "K", "k", "G", "g"}
# The second letter of the pair: bare c/C, with or without the dot.
C_TOKENS = {"c", "C", ".C", ".c"}
J_TOKENS_START = {"j", "J"}


def step(carry, prefix, upstream):
    """Activation at the newest position, from the newest token and the one before it."""
    cur = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    if cur in FC_TOKENS:
        return carry, 4.5
    if cur in J_TOKENS:
        return carry, -2.0
    if prev in LEADING_LETTERS:
        if cur in C_TOKENS:
            return carry, 3.5
        if cur in J_TOKENS_START:
            return carry, -1.7
    return carry, 0.0

programs.sol:
"""A detector for numerical precision and for introducing mathematical operands.

It responds to continued decimal fractions and to phrases such as 'in terms
of', 'as a function of', 'proportional to', and 'quadratic ... in'. Ordinary
uses of the same words are weaker. Recent algebraic notation helps distinguish
the mathematical readings. Small additional rules cover exponents, plot labels,
quantity adjectives, and a negative response to a document-initial heading marker.
Only the last 200 characters are retained, separately for each document.
This is an approximation, not a general math parser.
"""
import math
import re
from functools import lru_cache
import inflect

READS = ()
_INFLECT = inflect.engine()
OPERATORS = set('factor multiple power derivative divisor product permutation '
                'combination exponent logarithm integral'.split())
COLLECTIONS = set('series sequence subset pair set'.split())
MODIFIERS = set('linear quadratic cubic polynomial exponential logarithmic '
                'trigonometric smooth continuous differentiable periodic '
                'increasing decreasing monotonic positive negative arbitrary'.split())
SCALES = set('large small larger smaller high low higher lower constant fixed '
             'increasing decreasing'.split())
ALGEBRA = re.compile(
    r'[=^\\]|\$(?!\s*\d)|\b[bcdfghkmnpqruvxyz]\b|'
    r'\b(?:equations?|quadratic|polynomial|algebra|derivative|express|expressed|'
    r'expression|variables?|complex|coordinates|matrix|velocity|speed|integral|'
    r'curve|slope|angle|gauge|orbit)\b')


@lru_cache(maxsize=4096)
def singular(word):
    if not word:
        return word
    return _INFLECT.singular_noun(word) or word


def response(before, token, start):
    # Digits following a decimal point: one-based fractional position.
    if len(token) == 1 and token in '0123456789':
        m = re.search(r'\.([0-9]*)$', before)
        if not m:
            return 0.0
        n = len(m[1]) + 1
        if n == 1:
            return 0.06
        if n == 2:
            return 0.57 if token == '0' else 0.93
        peak = 0.62 if token == '0' else 1.33
        return peak * math.exp(-0.25 * max(0, n - 4))
    if token == '#' and start:
        return -1.48
    if token.startswith('^'):
        return 0.82 if '(' in token or '-' in token else 0.10
    if token == "('" and re.search(r'\b(?:xlabel|ylabel|zlabel|title)$', before):
        return 2.30
    full = before + token
    if re.search(r'\bw\.?r\.?t$', full):
        return 4.2

    word = token.strip().lower()
    if not word.isalpha():
        return 0.0
    m = re.search(r'([A-Za-z]+)\s*$', before)
    p = m[1].lower() if m else ''
    m2 = re.search(r'([A-Za-z]+)\s*$', before[:m.start()]) if m else None
    q = m2[1].lower() if m2 else ''
    recent = before[-160:]
    if len(before) >= 160:  # Do not mistake a cut-off word ending for a variable.
        recent = recent.partition(' ')[2]
    algebra = bool(ALGEBRA.search(recent.lower()))
    writing = p == 'in' and q in ('write', 'written', 'expressed')

    if word == 'terms' and p == 'in':
        return 0.8 + 2.55 * (algebra or writing)
    if word == 'of':
        if p == 'terms' and q == 'in':
            return 0.6 + 3.15 * algebra
        if p == 'function':
            if re.search(r'\bas\s+a\s+function\s*$', before.lower()):
                return 10.8
            if q == 'a':
                return 6.3
            return 6.8 if q in MODIFIERS else 1.25
        noun = singular(p)
        if noun == 'power':
            mathematical = algebra or q == 'a' or any(c.isdigit() for c in recent)
            return 2.36 if mathematical else 0.03
        if noun in OPERATORS:
            return 3.8 if noun == 'combination' and q == 'linear' else 0.84
        if p in ('independent', 'dependence', 'dependent', 'functional'):
            return 1.0
        if noun in COLLECTIONS:
            return 0.29
        if noun == 'value':
            return 0.28
    if word == 'function':
        value = -0.19 + 0.12 * algebra
        if p == 'a':
            return value + 0.49 + 4.14 * (q == 'as')
        return value + 1.62 * (p in MODIFIERS)
    if word == 'respect' and p == 'with':
        return 1.34 + 1.04 * algebra
    if word == 'to':
        if p == 'respect' and q == 'with':
            return 2.0 + 1.76 * algebra
        if p == 'proportional':
            return 3.28
        if p in ('relative', 'perpendicular', 'parallel', 'sensitive'):
            return 1.0
    if word == 'in':
        if p == 'quadratic':
            return 9.8
        if q == 'quadratic' and p in ('equation', 'polynomial', 'form'):
            return 11.5
        if q == 'linear' and p in ('system', 'equation'):
            return 6.0
        if p in ('equation', 'equations', 'system', 'formula', 'polynomial'):
            return 1.38
        if p in ('dense', 'uniform', 'homogeneous', 'analytic'):
            return 1.9
        if p in ('terms', 'term', 'square', 'circle', 'root'):
            return 0.79
        if p in ('expressed', 'express', 'write', 'written', 'plugging'):
            return 0.73
    if word == 'on' and (p in ('dependent', 'independent', 'depends', 'dependence') or
                         (p == 'only' and q in ('depends', 'depend'))):
        return 0.41
    if word == 'by':
        if p == 'divisible':
            return 2.1
        if p in ('multiply', 'multiplying', 'multiplied', 'divide', 'divided',
                 'dividing', 'division', 'sides', 'denominator'):
            return 1.1
    if word == 'for' and p in ('solve', 'solving'):
        return 2.63
    if word == 'between' and p in ('relation', 'relations', 'relationship',
                                   'relationships', 'correspondence'):
        return 1.28
    if word == 'unit' and p == 'per':
        return 2.9
    if word == 'with' and p in ('linearly', 'quadratically', 'increases',
                                'decreases', 'varies', 'vary', 'varying'):
        return 2.12
    if word == 'involving' and singular(p) in (
            'term', 'expression', 'relation', 'equation', 'inequality', 'cycle'):
        return 3.6
    if word == 'combination' and p == 'linear':
        return 3.8
    if word == 'change' and p == 'of' and q == 'rate':
        return 3.0
    if word in SCALES:
        if word in ('increasing', 'decreasing') and p == 'with':
            return 3.0
        if word in ('large', 'small') and p in ('for', 'all'):
            return 1.5 + 0.7 * algebra
        return 0.15 + 0.28 * algebra
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(before, token, not before)
    return (doc, (before + token)[-200:]), float(value)

"""Approximate a boundary-sensitive language-stem response.

Language, tongue and writing vocabulary receives negative values, strengthened
by spoken-language qualifiers. Short ng + vowel fragments are negative
(especially ng + ua); some consonant continuations are positive. Bare
github.com, lang + .org, and an opening Title: label are separate cases.
Other tokens receive zero. Latin initial-vowel accents are ignored.
The state holds only the previous token and an 80-character text tail.
"""
import re
import unicodedata
import pycountry

READS = ()
LANGUAGE_NAMES = frozenset(
    name.casefold()
    for language in pycountry.languages
    for name in (language.name,
                 getattr(language, 'inverted_name', language.name).split(',')[0])
)
SPOKEN = frozenset(
    'first second native foreign local world global national indigenous'.split()
)
RELATIVE = frozenset(
    'own other another all various universal same latter mother'.split()
)
ABSTRACT = frozenset(
    'natural programming formal artificial body plain explicit specific medical '
    'precise functional original human written ai'.split()
)


def predict(token, previous, left):
    s, p = token.casefold(), previous.casefold()
    # A separate document-initial title-label response.
    if left == 'Title' and token == ':':
        return -8.4
    word = s.strip(' _-\t\n')
    if word in ('language', 'languages'):
        words = re.findall(r'[^\W\d_]+', left)
        last_word = words[-1] if words else ''
        modifier = last_word.casefold()
        title = token.strip(' _-\t\n')[:1].isupper()
        if modifier in ABSTRACT:
            return -0.2
        if modifier in SPOKEN:
            return -4.4 if title else -3.3
        if (modifier in LANGUAGE_NAMES
                and (last_word[:1].isupper() or len(modifier) >= 4)) or modifier in {
            'indian', 'semitic', 'celtic', 'slavic', 'germanic', 'romance'
        }:
            return -3.3 if title else -2.6
        if modifier in RELATIVE:
            return -1.7
        if title:
            return -0.6
        if not token[0].isspace() and token[0].islower():
            return -0.2
        return -1.0 if word.endswith('s') else -0.6
    if 'ilingual' in s:
        return -4.9
    if (any(stem in s for stem in ('lingu', 'langu', 'lengu'))
            or re.fullmatch('[aeiou]ngu', s)):
        return -2.9
    if word in ('tongue', 'tongues'):
        return -4.1
    if (s == '.com' and left.casefold().endswith('github')
            and not left.casefold().endswith('.github')):
        return -1.5
    if s == '.org' and p.endswith('lang') and len(p.strip()) <= 5:
        return -1.8
    # Chinese speech/writing words and Korean language-name endings.
    if s in ('语', '語'):
        return (-3.5 if p.endswith(('国', '國'))
                else -0.6)
    if s in ('语言', '語言', '文字'):
        return -1.7
    if s == '어' and p.endswith(('국', '영')):
        return -3.6
    # Fold Latin vowel accents, e.g. ng + ü, but do not transliterate scripts.
    if s:
        initial = unicodedata.normalize('NFD', s[0])[0]
        s = initial + s[1:]
    # These are continuations inside a word, not words following a space.
    if not s or not s[0].isascii() or not s[0].isalpha():
        return 0.0
    if p.endswith('ng') and len(p.strip()) <= 5:
        if s.startswith('gu'):
            return -1.0
        if s.startswith('ua'):
            return -10.9
        if s.startswith('u'):
            return -4.4 if len(s) <= 3 else -0.4
        if s[0] in 'aeio':
            return -0.3
        if s[0] in 'kgjz':
            return 2.1
        if s[0] in 'ctd':
            return 0.5
        if s[0] in 'lhw':
            return 0.0
        return 0.3
    if p.endswith('ngu') and len(p.strip()) <= 5:
        return -5.5
    if p.endswith('ngl') and len(p.strip()) <= 5:
        return -2.8
    if p.endswith('nge') and len(p.strip()) <= 4:
        return -0.2
    if p.endswith('n') and s.startswith('g') and len(s) <= 3:
        return 0.4
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, left = '', ''
    else:
        _, previous, left = carry
    token = prefix.token_strings[-1]
    value = predict(token, previous, left)
    return (document, token, (left + token)[-80:]), value

