"""layers.1.mlp.down_proj:5933: a "language word" detector that also reads the letter after "ng".

What it does: almost always 0. It is negative on words about languages and tongues, in
English and in a few CJK characters:
  - the piece that completes a word built on the stems ling-, leng-, lang-, deng-, tongue
    (accents folded, so língua counts) when the word is split across tokens:
    ling|ua (lingua), ling|ual (lingual), ling|ui, ling|us, deng|ue (dengue),
    lengu|aje, sociolingu|istic, lingu|ist: about -6 (down to -12);
  - whole words: tongue about -4.5, linguistic about -4, language/languages about -1,
    and a token that contains "language" (like -language) about -2;
  - the CJK characters 语, 語 and 舌 (language, tongue): about -1 (舌 more).
Right after a piece that ends in "ng", the sign follows the next letter: a u-piece is
about -2, o about -1, and a k, g, j or f piece about +3, +3, +2, +1.5 (names like Sung|k|ook).
A github ".com" is about -2, and the colon of a "Title:" label is about -3.

Why: a handful of plain rules over the current word and the previous piece, so a reader can
see what the component responds to. A table of token activations would explain more, but it
would not say what the component is about.
"""
import unicodedata

READS = ()

STEMS = ("ling", "leng", "lang", "deng", "tongue")
COMPLETING_PIECES = {"ua", "ual", "ue", "ui", "us", "ul", "uez", "uel", "ist", "istic",
                     "aje", "ish", "ished", "ishes", "ishing", "ingual", "uish"}
WHOLE_WORDS = {" tongue": -4.5, " linguistic": -4.0, " language": -1.0, " languages": -1.3,
               " Language": -1.5, " Languages": -1.5}
CJK_WORDS = {"语": -1.0, "語": -1.0, "舌": -3.0}
NG_VALUES = {"u": -2.0, "o": -1.0, "k": 3.0, "g": 3.0, "j": 2.0, "f": 1.5}


def fold(text):
    """Lowercase, with accents removed (língua -> lingua)."""
    decomposed = unicodedata.normalize("NFD", text)
    return "".join(c for c in decomposed if unicodedata.category(c) != "Mn").lower()


def word_pieces(prefix):
    """Folded pieces of the word that ends at the current token (prefix only)."""
    t = prefix.position
    pieces = []
    i = t
    while i >= 0 and prefix.document_ids[i] == prefix.document_ids[t]:
        token = prefix.token_strings[i]
        core = token.lstrip(" ")
        if not core or not core[0].isalpha():
            break
        pieces.insert(0, fold(core))
        if core != token:  # a token with a leading space starts the word
            break
        i -= 1
    return pieces


def step(carry, prefix, upstream):
    token = prefix.token_strings[prefix.position]
    if token in WHOLE_WORDS:
        return carry, WHOLE_WORDS[token]
    if token in CJK_WORDS:
        return carry, CJK_WORDS[token]
    folded = fold(token)
    if "tongue" in folded:
        return carry, -4.5
    if "languag" in folded:
        return carry, -2.0 if "-" in token else -1.0
    pieces = word_pieces(prefix)
    if len(pieces) > 1:
        before, last = "".join(pieces[:-1]), pieces[-1]
        if any(stem in before for stem in STEMS) and last in COMPLETING_PIECES:
            return carry, -6.0
        if "lingu" in last:
            return carry, -4.0
    t = prefix.position
    previous = fold(prefix.token_strings[t - 1]) if t > 0 else ""
    if previous.endswith("ng") and token[:1].isalpha() and not token.startswith(" "):
        return carry, NG_VALUES.get(folded[:1], 0.0)
    if token == ":" and previous == "title":  # a "Title:" label opening a document
        return carry, -3.0
    if token == ".com" and previous.endswith("github"):
        return carry, -2.0
    return carry, 0.0

