"""Selective responses to familiar boilerplate and short collocations.

The strongest negatives mark Java/Android/.NET qualifiers, an opening
'Title:' header, and PHP's opening tag. Additional rules cover namespace
names, Chinese national-sector phrases and a formal salutation. Source-file
openings and repeated middle-dot leaders can instead be positive.
Unrecognized text receives zero, not a general punctuation response.
"""
import regex
from opencc import OpenCC

SIMPLIFY = OpenCC('t2s')
READS = ()

# Standard-library package families; names, not tokenizer IDs.
JAVA = {
    '.util': -15.4, '.io': -15.1, '.text': -13.9,
    '.math': -16.7, '.net': -11.9, '.sql': -14.5,
    '.awt': -7.9, '.lang': -7.8, '.nio': -7.3, '.time': -5.6,
}
ANDROID = {
    '.content': -10.7, '.view': -9.2, '.widget': -9.1,
    '.os': -6.1, '.graphics': -5.0, '.app': -4.8,
    '.permission': -2.2,
}
DOTNET = {
    '.Text': -5.8, '.Collections': -2.5, '.Net': -9.4,
    '.IO': -6.1, '.Data': -6.4, '.Threading': -3.5,
    '.Runtime': -3.5, '.Drawing': -2.9, '.ComponentModel': -3.0,
}

NATIONAL_SECTORS = {
    '农业', '教育', '科学院', '科学技术', '社会', '银行', '工程机械',
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
        previous, position = carry[1], carry[2] + 1
    name = previous.strip().lstrip('("')
    value = 0.0
    if position == 1 and previous == 'Title' and token == ':':
        value = -19.03
    elif previous.endswith('<?') and token == 'php':
        value = -5.0 if position == 1 else -1.0
    elif name == 'java':
        # JNI-style names use underscores instead of dots.
        key = '.' + token[1:] if token.startswith('_') else token
        value = JAVA.get(key, 0.0) * (0.45 if token.startswith('_') else 1.0)
    elif name == 'android':
        value = ANDROID.get(token, 0.0)
    elif name == 'System':
        value = DOTNET.get(token, 0.0)
    elif name == 'com' and token.startswith('.') and token[1:].isalpha():
        value = -5.4 if token == '.google' else -0.75
    elif name == 'org' and token.startswith('.') and token[1:].isalpha():
        value = -5.8 if token in {'.apache', '.json'} else -0.7
    elif previous.endswith('/com') and token == '/google':
        value = -5.5
    elif previous.endswith('/org') and token == '/apache':
        value = -2.1
    elif name == 'std' and token == '::':
        value = -1.65
    elif name == 'github' and token == '.com':
        value = -1.7
    elif previous.endswith('.com') and token == '/google':
        value = -2.5
    elif previous.strip() == '@' and token == 'event':
        value = 2.2
    elif name == 'Java' and token == '_com':
        value = -2.6
    elif previous.strip() == '尊敬' and token == '的':
        value = -8.7
    elif previous.endswith(('中国', '中國')):
        chinese = SIMPLIFY.convert(token)
        if chinese in {'人民', '工程'}:
            value = -9.3
        elif chinese in NATIONAL_SECTORS:
            value = -4.5
        elif regex.fullmatch(r'\p{Script=Han}+', chinese):
            value = -1.5
    elif previous == token == '··':
        value = 1.3
    elif position == 0 and token == 'package':
        value = 4.35
    elif position == 0 and token in {'import', 'from', 'using', '#include'}:
        value = 1.5
    elif token == 'Script' and previous == ' Native':
        value = 4.3
    return (doc, token, position), value

"""A spelling detector for 'et', including accented and related alphabets.

Short, exposed et fragments are stronger than et buried in a long word.
An e followed by t in the next token also counts, and a short continuation
can retain the signal.  The ordinary French conjunction et is much weaker
than the same spelling in English text (often an author's 'et al.').
Small rules distinguish Russian demonstrative inflections and East Asian
e+t spellings. Outside these spelling patterns the prediction is zero.
The numbers are approximate training-set means, not a token lookup table.
"""
import re
import codecs
import regex
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
ALPHABETS = r'[\p{Latin}\p{Greek}\p{Cyrillic}\p{Katakana}\p{Hangul}]'


@lru_cache(maxsize=50000)
def roman(text):
    return anyascii(text).lower()


@lru_cache(maxsize=50000)
def frequency(word, language='en'):
    return zipf_frequency(word, language)


def french_context(text):
    words = re.findall(r'[^\W\d_]+', text.lower())[-12:]
    if not words:
        return 0.0
    return sum(frequency(w, 'fr') - frequency(w) for w in words) / len(words)


def activation(s, previous, word, recent):
    if not regex.search(ALPHABETS, s):
        return 0.0
    stem = s.strip().lower()
    # Gender/case forms of the Russian demonstrative 'this'.
    if stem in {'эта', 'эти', 'этой', 'этих'}:
        return 2.6 + float(s.strip()[:1].isupper())
    if stem in {'этот', 'эту'}:
        return 1.4 + float(s.strip()[:1].isupper())
    if stem == 'это':
        return 0.03
    a, b = roman(s), roman(previous)
    camel_boundary = s[:1].isupper() and previous[-1:].islower()
