import re

READS = ()

ET_SPELLING = re.compile(r"et|ет|эт")  # Latin e then t, or Cyrillic е/э then т
WHOLE_WORDS = {"let", "set", "get", "yet", "met", "net", "bet", "pet", "jet", "wet", "sent"}
TI_TS = {"ti", "ts", "tt", "tn"}  # weaker, related fragments
FRENCH = re.compile(r"[éèàçùôêâîëœ]|\b(les|des|une|est|qui|dans|pour|avec|sont|nous|vous)\b")


def previous_word(strings):
    """The word that ends just before the current token (its pieces, joined)."""
    word = ""
    for piece in reversed(strings[:-1]):
        word = piece + word
        if piece[:1].isspace():
            break
    return re.sub(r"^\W+", "", word)


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    current = strings[-1]
    piece = current.strip().lower()
    if piece == "et" and current.startswith(" "):
        if previous_word(strings)[:1].isupper():
            in_parens = any("(" in s for s in strings[-5:-1])
            value = 3.5 if in_parens else 2.6  # "Schweder et al.", "(Fisher et al."
        elif FRENCH.search("".join(strings[-20:-1])):
            value = 0.25  # the French "et" (and)
        else:
            value = 2.0  # "et" in Latin or English text, e.g. "et cetera"
    elif piece == "et":
        value = 0.8  # "et" inside a longer word, e.g. "Ven|et|ian"
    elif ET_SPELLING.search(piece):
        if piece.isascii() and len(piece) <= 3 and piece not in WHOLE_WORDS:
            value = 0.9  # a short Latin fragment: ret, eth, ety
        elif not piece.isascii():
            value = 0.4  # Cyrillic: ет, эти, этот
        else:
            value = 0.15  # longer words that contain et, e.g. let, return
    elif piece in TI_TS:
        value = 0.25
    else:
        value = 0.0
    return carry, value

