"""Approximate English references to a task's premises and requirements.

The strongest cues are 'the problem', 'problem says/states', and 'given'.
Short following connectives retain part of the response. A few formatting
rules distinguish introducing premises from introducing an example or title.
This is a lexical/phrase approximation, not a parser of the problem itself.
"""
from functools import lru_cache
import wordnet

READS = ()
TASK = {'problem', 'question', 'task', 'exercise', 'puzzle'}
SOURCE = TASK | {'user', 'instruction', 'instructions', 'statement',
                 'description', 'wording', 'note', 'text', 'example', 'prompt'}
REPORT = {'say', 'state', 'mention', 'tell', 'specify', 'give', 'describe'}
NEED = {'need', 'want', 'ask', 'require', 'intend', 'suppose'}
INFO = {'information', 'detail', 'data', 'input', 'instruction', 'requirement',
        'condition', 'constraint', 'specification', 'assumption', 'description',
        'wording', 'variable', 'equation'}
PURPOSE = {'goal', 'goals', 'objective', 'objectives', 'aim', 'aims', 'purpose'}
DET = {'the', 'this', 'that', 'our', 'your', 'my', 'its', 'a', 'an'}
PERSON = {'we', 'you', 'i', 'they', 'he', 'she', 'it', 'one'}
COPULA = {'is', 'are', 'was', 'were', 'be', 'been'}
LINK = {'to', 'that', 'is', 'are', 'be', 'as', 'of', 'and', 'with',
        'for', 'the', 'a', 'an', 'in', 'it', 'this'}


@lru_cache(maxsize=32768)
def root(word):
    classes = REPORT | NEED | INFO
    if word in classes or not word.isalpha():
        return word
    return next((b for b in wordnet.base_forms(word) if b in classes), word)


