    doc = int(prefix.document_ids[-1])
    history = carry[1] if carry is not None and carry[0] == doc else []
    previous = carry[2] if carry is not None and carry[0] == doc else 0.0
    raw = prefix.token_strings[-1]
    w = raw.strip().lower()
    words = [s.strip().lower() for s in history]
    p = words[-1] if words else ''
    q = words[-2] if len(words) > 1 else ''
    punct = bool(w) and not any(c.isalnum() for c in w)
    value = 0.0

    # Naming a task, especially a particular task being referred back to.
    if w in TASK:
        value = .85 if w == 'problem' else .1
        if p in DET:
            value += 2.1 if p == 'the' else .45
            if q == 'in':
                value += 1.6
        if 'given' in words[-3:]:
            value += 1.75
        if 'according' in words:
            value += 4.2
        if any(s in {'but', 'wait', 'however'} for s in words):
            value += 1.35
    if w in {'problems', 'questions', 'tasks'}:
        value += .2
    if w in {'statement', 'statements'}:
        value += .4 + (5.3 if p in TASK else 0)
    if root(w) in INFO:
        value += .2 + (.2 if p in DET else 0)
        if w in {'instruction', 'instructions', 'conditions', 'constraints'}:
            value += .25
        if 'given' in words[-3:]:
            value += .55
        if p == 'given' and w in {'information', 'conditions', 'constraints'}:
            value += 3.1
    if w in PURPOSE:
        value += .2

    # Stating what a problem says is stronger than ordinary reported speech.
    if root(w) in REPORT and w != 'given':
        value += 1.4 if w.startswith('mention') else .1
        if w in {'says', 'states', 'specifies'}:
            value += .7
        if w == 'states' and p == 'united':
            value = 0.0
        elif p in TASK:
            value += 8.3 if w in {'says', 'states'} else 5.5
        elif any(s in TASK for s in words[-4:]):
            value += 3.0
        elif p in SOURCE:
            value += 2.2
        elif any(s in SOURCE for s in words):
            value += .5
        if p in {'it', 'that', 'this'}:
            value += .6
        if p in COPULA:
            value += .4

    # Premises received, and actions requested or required.
    if root(w) in NEED:
        value += .5 if w == 'asking' else .3
        if p in PERSON:
            value += .25 + (1.2 if p == 'we' else 0)
        if p in TASK:
            value += 3.7
        elif any(s in SOURCE for s in words[-4:]):
            value += 1.1
        if w == 'asking' and p in COPULA and q in TASK:
            value += 4.2
    if w == 'given':
        value += .65 + (.45 if raw.strip() == 'Given' else 0)
        if p in DET:
            value += .35
        if not words and raw.strip() == 'given':
            value += 4.0
    if w in {'given', 'told', 'required', 'asked', 'supposed'} and p in COPULA:
        value += .5
        if q in {'we', 'you'}:
            value += 2.8
    if w == 'know' and p == 'we':
        value += 1.85
    if w in {'original', 'initial'}:
        value += .4
    if w == 'also':
        value += .2
    if w in {'since', 'because'}:
        value += .5 if raw.strip()[0].isupper() else .1
    if w in {'must', 'shall'}:
        value += .25
    if w in {'user', 'instruction', 'description', 'wording'} and p == 'the':
        value += .6

