        value += previous * (.25 if p in LINK else .45)
    if w == 'as' and p == 'given':
        value += 3.5
    if w == 'to' and p == 'have':
        value += .6
    if w in {"'s", '’s'} and p in TASK:
        value += 3.0
    if w.startswith(':'):
        value += .25 if '\n' in raw else 0
        if p == 'given':
            value += 2.1
        if p == 'title' and len(words) == 1:
            value = -6.15
    if w.startswith('"') and p.startswith(':'):
        value += 1.4 if any(s in SOURCE for s in words) else .15
    if w.startswith(',') and p == 'example' and q == 'for':
        value -= 1.0 if history[-2].strip() == 'For' else .1
    return (doc, (history + [raw])[-6:], value), value

"""An orthographic approximation, centered on -ic and -ics fragments.

Few vowel groups in the preceding stem make the response more negative;
pt-ending stems and comic/comics have stronger responses. A split-off
ic/ics is treated differently from a whole word. Common whole words are
weaker than rare ones. Small secondary rules cover short-stem ess,
c + red, and repeated double middle-dot separators (positive).
Only the current alphabetic word and previous token are carried forward.
"""
import re
from wordfreq import zipf_frequency

READS = ()


def response(token, word, previous):
    lower = token.lower()
    if lower.endswith(('ic', 'ics')):
        plural = word.lower().endswith('ics')
        ending_length = 3 if plural else 2
        stem = word.lower()[:-ending_length]
        vowels = len(re.findall(r'[aeiouy]+', stem))
        if stem.endswith('pt') and (vowels <= 1 or stem.endswith('ipt')):
            return -3.5
        if stem == 'com':
            return -2.1 if plural else -4.7
        if lower in ('ic', 'ics') and len(stem) == 0:
            return -0.5
        if lower in ('ic', 'ics'):
            if vowels <= 1:
                if stem.endswith('d'):
                    return -0.6
                return -2.45 if previous.startswith(' ') else -1.5
            if vowels == 2:
                return -0.8
            return -0.3
        continuation = token.isalpha() and len(word) > len(token)
        if continuation:
            initial = word[:-len(token)]
            if (not re.search('[aeiouy]', initial.lower())
                    and vowels <= 1
                    and zipf_frequency(word.lower(), 'en') < 3):
                return -1.5
        if vowels <= 1:
            frequency = zipf_frequency(word.lower(), 'en')
            return -0.6 if frequency < 4 else -0.1
        return 0.02
    if token == previous == '··':
        return 1.6
    if lower == 'ess' and 0 < len(word) - 3 <= 2:
        return -2.4
    if lower == 'red' and word.lower().endswith('cred'):
        return -2.5
    return -0.0025


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        old_word, previous = '', ''
    else:
        _, old_word, previous = carry
    token = prefix.token_strings[-1]
    match = re.search(r'[A-Za-z]+\Z', old_word + token)
    word = match.group()[-80:] if match else ''
    value = response(token, word, previous)
    return (document, word, token), value

