"""Set-introducing words in mathematical text.

Component layers.1.mlp.down_proj:5941 fires on the word or symbol that introduces a set,
domain, space or range in mathematics, at the position of that word, before the set is
named: "x in [0, 1]", "is in S", "element of", "subset of", "measure on", "dense in",
"\\in" (LaTeX), "∈", and the middle dot "··". It is nearly silent on ordinary prose.

The program scores each token from the prefix alone:
  * symbols for set membership and inclusion ("∈", "⊆", ...) and "··" get fixed values;
  * "in" after a LaTeX backslash (\\in, Isabelle \\<in>) is strong when the text around
    it is math-dense;
  * a preposition ("in", "on", "of", "between", "from", "over", "within") gets a value
    from the word before it: a set noun such as subset or element, a single-letter
    variable ("x in"), a be-verb ("is in"), or, otherwise, the math density of the last
    20 tokens. "of" only fires after a set noun.
  * plain set nouns (set, interval, domain, space, ...) get a small value.
"""

READS = ()

import re

SYMBOLS = {"∈": 5.8, "⊆": 4.5, "⊂": 4.0, "∉": 3.0, "··": 1.3}
LATEX_RELATIONS = {"in", "notin", "subset", "subseteq", "subsetneq", "<"}
SET_NOUNS = {"subset", "subsets", "subseteq", "subspace", "interval", "intervals", "domain",
             "range", "set", "sets", "space", "union", "intersection", "element", "elements",
             "measure", "dense", "inclusion", "belongs", "lie", "lies", "integers", "pace", "empty"}
STRONG = {"subset", "subsets", "pace", "lie", "dense"}
MEDIUM = {"element", "measure", "integers", "closed", "supported", "interval", "elements"}
BE_VERBS = {"is", "be", "are", "lies", "lie", "lying", "was", "being"}
PREPOSITIONS = {"in", "on", "of", "between", "from", "over", "within"}
MATH_MARK = re.compile(r"[\\$^_{}=<>+*/|0-9∈⊆∀∃ℝ≤≥]")


def is_math(t):
    """A token that looks like mathematics: LaTeX, operators, digits, or a single letter."""
    return bool(MATH_MARK.search(t)) or (len(t) == 1 and t.isalpha())


def step(carry, prefix, upstream):
    toks = [t.strip() for t in prefix.token_strings]
    s = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    if s in SYMBOLS:
        return None, SYMBOLS[s]
    recent = toks[-21:-1]
    density = sum(is_math(t) for t in recent) / max(len(recent), 1)
    if "\\" in prev and s in LATEX_RELATIONS:
        return None, 5.4 * min(1.0, 2 * density)
    if s in SET_NOUNS:
        return None, 0.2
    if s in PREPOSITIONS:
        if prev in STRONG:
            return None, 3.8
        if prev in MEDIUM:
            return None, 1.4
        if s == "of":
            return None, 0.0
        if prev in BE_VERBS:
            return None, 3.6 * density
        if len(prev) == 1 and prev.isalpha():
            return None, 0.3 + 2.3 * density
        return None, 0.43 * density
    return None, 0.0

