import regex

READS = ()
POSSESSIVES = frozenset(
    "my your his her its our their mine yours hers ours theirs".split()
)
BLANK_AFTER = {
    "<think>": 0.41,
    "</think>": 0.33,
    "<tool_response>": 0.32,
}
NEWLINE_AFTER = {
    "assistant": -0.026,
    "user": 0.012,
    "<tool_call>": 0.035,
    "<tool_response>": 0.035,
    "<|im_end|>": 0.0,
}


