    if position == 1:
        if previous == "1" and text == "2":
            return 2.80
        if previous == "Title" and text == ":":
            return -3.097
    if position == 2 and first == "1" and previous == text == "2":
        return 1.05

    if text == "\n\n":
        if position == 0:
            return -0.32
        return BLANK_AFTER.get(previous, 0.05)
    if text == "\n":
        if position == 0:
            return 0.045
        return NEWLINE_AFTER.get(previous, -0.018)

    word = text.strip()
    hashes = bool(word) and set(word) == {"#"} and "\n" not in text
    if position == 0:
        if word.lower() in POSSESSIVES:
            return -0.85
        if hashes:
            return -0.55
        if regex.search(r"\p{Script=Greek}", text):
            return 0.77
        if regex.search(r"\p{Script=Cyrillic}", text):
            return 0.18
        if regex.search(r"\p{Script=Han}", text):
            return -0.115
        if text in {"import", "from"}:
            return -0.92
        if text == "Question":
            return -1.447
        if word.isascii() and word.isalpha():
            if word.isupper() and len(word) > 1:
                return 0.15
            if word.islower() and word.endswith("ed"):
                return 0.21
