            return 1.506
        if text == "\\n":
            return 0.557

    if text == "\\n":
        return -0.057
    if "\\" in text and ('"' in text or "'" in text):
        return -0.057
    if text == "  ":
        return 0.241 if position == 0 else 0.038
    if text == " ":
        return -0.082 if position == 0 else 0.0
    if hashes:
        return -0.03
    if text.isspace() and "\n" not in text and "\t" in text:
        return 0.23 if position == 0 else -0.02
    return 0.0


