    document = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        previous, position, first = "", 0, text
    else:
        _, previous, position, first = carry
    value = predict(text, previous, position, first)
    return (document, text, position + 1, first), value

