before it, within the same document, and returns one fixed value per pattern. Every
other position predicts 0.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

PAGE_WORDS = {"page", "pg"}
COUNT_WORDS = {"step", "part", "article", "entry", "chapter"}

PAGE_OF = -6.4  # "Page 3 of 12"
COUNT_OF = -3.0  # "Step 2 of 6"
NUMBER_OF = -0.4  # any other "3 of ..."
CODE_OPEN = -2.5  # a backtick opening a code span at the start of a line


def back(prefix, k):
    """The token k steps before the current one, or '' if it is in an earlier document."""
    i = prefix.position - k
    if i < 0 or prefix.document_ids[i] != prefix.document_ids[-1]:
        return ""
    return prefix.token_strings[i]


def word_before_number(prefix):
    """The word just before the number that comes right before the current token."""
    if not back(prefix, 1).strip().isdigit():
        return None
    k = 1
    while is_digit_or_space(back(prefix, k)):
        k += 1
    return back(prefix, k).strip().lower()


def is_digit_or_space(s):
    return s != "" and (s.strip() == "" or s.strip().isdigit())


def step(carry, prefix, upstream: Mapping):
    tok = prefix.token_strings[-1]
    prev = back(prefix, 1)
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        if tok.strip().isdigit():
            return carry, 0.3  # a document opening with a number
        if tok.strip() == "#":
            return carry, 0.5  # a document opening with a markdown heading
    if tok == " of":
        word = word_before_number(prefix)
        if word is None:
            return carry, 0.0
        if word in PAGE_WORDS:
            return carry, PAGE_OF
        if word in COUNT_WORDS:
            return carry, COUNT_OF
        return carry, NUMBER_OF
    if tok.strip() == "`" and "\n" in prev:
        return carry, CODE_OPEN
    if tok == "permalink":
        return carry, 1.6
    if tok == "posted" and "\n" in prev:
        return carry, 1.4
    if tok.strip() == "contributed" and prev == " is":
        return carry, 3.0
    return carry, 0.0

