There are also document-initial estimates for five source-code keywords.
Everything else is zero. Only the preceding token is retained, with a
reset at document boundaries; no longer-range context is modeled.
"""

READS = ()

# Domain words: strength of their technical-compound response.
MODIFIERS = {
    'data': 2.3, 'computer': 1.6, 'software': 1.4, 'app': 2.4,
    'application': 1.8, 'web': 1.9, 'website': 1.6, 'information': 2.1,
    'digital': 1.5, 'content': 1.4, 'media': 1.2, 'graphic': 1.2,
    'game': 1.5,
}

# Head nouns: strength when they complete a technical compound.
HEADS = {
    'structure': 1.6, 'science': 1.4, 'analysis': 0.8, 'analytics': 1.1,
    'mining': 0.9, 'model': 0.2, 'modeling': 1.0, 'privacy': 0.8,
    'management': 0.7, 'type': 0.1, 'center': 0.6, 'development': 2.0,
    'engineer': 2.5, 'engineering': 1.7, 'developer': 1.3,
    'scientist': 1.4, 'programming': 1.9, 'graphics': 1.1, 'system': 0.8,
    'software': 0.6, 'architecture': 1.0, 'security': 1.8,
    'experience': 1.5, 'interface': 0.7, 'design': 1.4, 'designer': 1.4,
    'hosting': 1.2, 'store': 0.5, 'marketing': 2.0, 'studies': 0.4,
    'production': 1.4, 'research': 1.6, 'computing': 0.5,
    'processing': 0.2, 'performance': 0.8, 'accessibility': 0.9,
}

# Other fixed technical/service expressions.
PHRASES = {
    'user': {'experience': 3.5, 'interface': 2.8, 'interfaces': 2.0},
    'customer': {'experience': 2.9, 'service': 0.5, 'support': 0.5},
    'cyber': {'security': 2.6},
    'machine': {'learning': 1.5, 'intelligence': 2.7},
    'artificial': {'intelligence': 1.2},
    'operating': {'system': 1.6, 'systems': 1.6},
    'file': {'system': 0.9, 'systems': 0.9},
    'distributed': {'system': 2.0, 'systems': 2.0},
    'programming': {'language': 1.0, 'languages': 1.0},
    'program': {'verification': 1.1},
    'version': {'control': 1.4},
    'network': {'monitoring': 1.3},
    'text': {'editor': 1.2},
    'video': {'games': 1.1, 'game': 0.5, 'editing': 0.9, 'production': 2.3},
    'youtube': {'channel': 0.65},
    'project': {'management': 0.7},
    'supply': {'chain': 0.9},
    'public': {'relations': 3.0, 'speaking': 4.0,
               'administration': 3.0},
    'operations': {'research': 4.1},
}

def predict(previous, token):
    p = previous.strip().lower()
    w = token.strip().lower()
    # Repeated middle-dot leaders are a negative layout cue.
    if token == '··' and previous == token:
        return -3.1
    if token == ' [' and (previous.isspace() or p == 'building'):
        if previous and not previous.strip(' '):
            return -1.1 if len(previous) + 1 in {4, 8} else -0.4
        if p == 'building':
            return -0.5
    if w in {'public', 'private', 'protected', '///', '[test'}:
        if previous in {'\t', '       '}:
            return -1.0
    if p in {'public', 'private', 'protected'}:
        if w == 'static':
            return -0.4
        if w == 'override':
            return -2.6
        if w == 'readonly':
            return -1.2
    if w == '__':
        return -0.12
    # These are word-internal pieces, not arbitrary graph/biology words.
    if not token.startswith(' '):
        if w in {'ograph', 'ographs', 'ographers', 'ographical'}:
            return -1.3
        if p in {'bibli', 'ibli', 'autobi'} and w == 'ography':
            return -1.5
        if p == 'app' and w in {'let', 'lets'}:
            return -3.2
        if p == 'bio' and w == 'informatics':
            return 1.3
    if p.lstrip('/') == 'test' and w == 'bed':
        return -0.2
    p = p.strip('/.-')
    w = w.strip('/.-')
    # Plural technical heads use the same strength as their singular form.
    if w.endswith('s') and w[:-1] in HEADS:
        w = w[:-1]
    if p == 'data':
        if w in {'set', 'sets', 'collection', 'protection'}:
            return -0.7
        if w == 'model':
            return 2.0 if token.startswith(' ') else 0.0
        if w == 'science':
            return 3.9
        if w == 'privacy':
            return 2.8 if token.startswith(' ') else 1.2
    if p in MODIFIERS and w in HEADS:
        return MODIFIERS[p] * HEADS[w]
    return PHRASES.get(p, {}).get(w, 0.0)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = predict(previous, token)
    if carry is None or carry[0] != doc:
        # Source-language openers have distinctive document-initial responses.
        value = {'using': 1.4, 'def': -1.9, '#include': 0.65,
                 'package': 0.4, 'const': 0.95}.get(token, value)
    return (doc, token), value
